import type { Article } from "../types";

/**
 * Loi n° 2024-014 du 14 août 2024 portant Code du travail (texte officiel, 394 articles).
 * Source : https://droit-et-politique-en-afrique.info/wp-content/uploads/2024/08/Loi-n%C2%B02024-014-du-14-aout-2024-portant-Code-du-travail-Madagascar.pdf
 * FICHIER GÉNÉRÉ par un script hors projet : `texte` est copié mot pour mot du texte officiel (seules différences : numéros de page retirés,
 * espaces normalisés, césures de fin de ligne recollées). Titres, résumés et mots-clés sont rédigés à la main.
 */
export const articles2024: Article[] = [
  { id: "l24-1", numero: "1", loi: "2024-014", theme: "Principes, discrimination et harcèlement", titre: "Champ d'application du Code", texte: "La présente loi est applicable à tout employeur et à tout travailleur dont le contrat de travail, quels que soient sa forme, le lieu de sa conclusion et la résidence de l'une ou de l'autre partie, est exécuté à Madagascar. Elle détermine les règles et principes applicables en matière de relations de travail individuelles aussi bien que collectives. Les dispositions du présent Code ne sont pas applicables aux agents publics régis par un statut général ou par un statut particulier, aux travailleurs indépendants et aux travailleurs régis par le Code maritime.", resume: "Le Code s'applique à tout employeur et travailleur dont le contrat est exécuté à Madagascar. Il ne s'applique pas aux agents publics sous statut, aux travailleurs indépendants ni aux travailleurs du Code maritime.", motsCles: ["champ d'application","employeur","travailleur","fonctionnaire","indépendant"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 1" },
  { id: "l24-2", numero: "2", loi: "2024-014", theme: "Principes, discrimination et harcèlement", titre: "Définition du travailleur", texte: "Est considéré comme travailleur au sens du présent Code, quels que soient son sexe et sa nationalité, toute personne qui s'est engagée à mettre son activité professionnelle, moyennant rémunération, sous la direction et l’autorité d'une autre personne physique ou morale, publique ou privée. Sont également considérés comme travailleurs au sens du présent Code : 1. les personnes rétribuées à la tâche ou aux pièces, dès lors qu’elles exécutent habituellement pour le compte d'une entreprise le travail par elles-mêmes, sans qu’il y ait lieu d’exiger d’elles de démontrer l’existence entre elles et leur employeur d’un lien de subordination juridique, ni à qui appartient le local, la matière mise en œuvre ou l'outillage qu'elles emploient; 2. les personnes exécutant habituellement pour le compte et sous l'autorité d'une autre personne le travail par elles-mêmes, quels que soient le mode de rémunération et la durée de travail ; 3. les travailleurs migrants et les travailleurs domestiques.", resume: "Est travailleur toute personne qui s'engage à travailler pour une rémunération sous la direction d'une autre, quels que soient son sexe et sa nationalité. Sont aussi travailleurs : les personnes payées à la tâche ou aux pièces, celles qui travaillent habituellement sous l'autorité d'une autre, les travailleurs migrants et domestiques.", motsCles: ["travailleur","définition","domestique","migrant","tâche"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 2" },
  { id: "l24-3", numero: "3", loi: "2024-014", theme: "Principes, discrimination et harcèlement", titre: "Définition de l'employeur", texte: "Est considéré comme employeur au sens du présent Code toute personne physique ou morale, individuelle ou collective, publique ou privée, dans l’économie formelle ou informelle, ayant ou non un but lucratif, quelle que soit sa nationalité, son statut, son secteur ou sa branche d'activité, qui, assumant les risques financiers, engage, rémunère et/ou dirige le personnel, qui loue ses services.", resume: "L'employeur est toute personne physique ou morale, publique ou privée, de l'économie formelle ou informelle, qui engage, rémunère ou dirige du personnel en assumant les risques financiers.", motsCles: ["employeur","définition","informel"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 3" },
  { id: "l24-4", numero: "4", loi: "2024-014", theme: "Principes, discrimination et harcèlement", titre: "Travail forcé interdit", texte: "Le travail forcé ou obligatoire est interdit. Le terme \"travail forcé ou obligatoire\" désigne tout travail ou service rémunéré ou non, exigé d'un individu sous la menace d'une peine quelconque ou d’une mesure négative et pour lequel ledit individu ne s'est pas offert de plein gré.", resume: "Le travail forcé ou obligatoire est interdit : tout travail exigé sous la menace d'une peine ou d'une mesure négative et pour lequel la personne ne s'est pas offerte de plein gré.", motsCles: ["travail forcé","interdit","menace"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 4" },
  { id: "l24-6", numero: "6", loi: "2024-014", theme: "Principes, discrimination et harcèlement", titre: "Discrimination interdite", texte: "Est interdite toute forme de discrimination directe ou indirecte en matière d’emploi ou de profession.", resume: "Toute forme de discrimination directe ou indirecte en matière d'emploi ou de profession est interdite.", motsCles: ["discrimination","interdite","égalité"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 6" },
  { id: "l24-7", numero: "7", loi: "2024-014", theme: "Principes, discrimination et harcèlement", titre: "Motifs de discrimination", texte: "La discrimination s’entend de toute distinction, exclusion ou préférence fondée sur la race, la couleur, le sexe, la religion, l'opinion politique, l'ascendance nationale (qui couvre les distinctions subies par des nationaux sur la base de leur pays de naissance, de leur ascendance ou de leur origine) ou l'origine sociale, l’état de santé, le handicap, l’appartenance syndicale, l’âge, les modes de vie et la situation de famille, qui a pour effet de détruire ou d'altérer l'égalité de chances ou de traitement en matière d'emploi ou de profession.", resume: "La discrimination est toute distinction, exclusion ou préférence fondée sur la race, la couleur, le sexe, la religion, l'opinion politique, l'ascendance nationale, l'origine sociale, l'état de santé, le handicap, l'appartenance syndicale, l'âge, les modes de vie ou la situation de famille, qui altère l'égalité de chances ou de traitement.", motsCles: ["discrimination","motifs","sexe","âge","handicap","syndicat","santé"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 7" },
  { id: "l24-10", numero: "10", loi: "2024-014", theme: "Principes, discrimination et harcèlement", titre: "Dignité et harcèlement sexuel", texte: "Tout salarié a droit au respect de sa dignité. Dans toutes les relations de travail, nul ne peut être victime de mauvais traitement ou de violence portant atteinte à l'intégrité physique ou morale prévue et sanctionnée par le Code pénal. Aucun salarié ne peut faire l'objet d'une sanction, ni d'une discrimination dans sa carrière ou dans son travail, ni d'un licenciement pour avoir résisté à des agissements de harcèlement d'un employeur, de son représentant ou de toute autre personne qui, abusant de l'autorité que lui confèrent ses fonctions, ses relations ou sa position dans l'entreprise, a donné des instructions, proféré des menaces, imposé des contraintes ou exercé des pressions de toute nature sur ce salarié dans le but d'obtenir des faveurs de nature sexuelle ou autres à son profit ou au profit d'un tiers. Est considéré comme harcèlement sexuel au travail, toute conduite non souhaitée, de nature sexuelle qui interfère avec le travail, conditionne l'emploi ou le déroulement normal de la carrière ou crée un environnement de travail intimidant. Aucun salarié ne peut faire l'objet d'une sanction, ni d'une discrimination dans sa carrière ou dans son travail, ni d'un licenciement pour avoir témoigné des agissements définis à l'alinéa précédent ou pour les avoir relatés.", resume: "Tout salarié a droit au respect de sa dignité. Nul ne peut être sanctionné, discriminé ni licencié pour avoir résisté à un harcèlement ou pour l'avoir relaté ou en avoir témoigné. Le harcèlement sexuel est défini : conduite non souhaitée de nature sexuelle qui interfère avec le travail, conditionne l'emploi ou la carrière ou crée un environnement intimidant.", motsCles: ["dignité","harcèlement sexuel","définition","témoin","violence"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 10", equivalent: "dignite-harcelement" },
  { id: "l24-11", numero: "11", loi: "2024-014", theme: "Principes, discrimination et harcèlement", titre: "Fouille corporelle", texte: "Lorsque la fouille corporelle du personnel, à l’entrée ou à la sortie du travail, est justifiée par la nature particulière du travail accompli ou par l’activité de l’entreprise, elle ne peut en aucune façon être pratiquée dans des conditions contraires à la dignité des salariés. Dans tous les cas, la fouille corporelle ne doit être effectuée que par une personne de même sexe que celle qui la subit.", resume: "La fouille corporelle à l'entrée ou à la sortie du travail, si elle est justifiée par la nature du travail, ne peut pas porter atteinte à la dignité et doit être faite par une personne du même sexe.", motsCles: ["fouille","dignité","sexe"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 11" },
  { id: "l24-12", numero: "12", loi: "2024-014", theme: "Principes, discrimination et harcèlement", titre: "Harcèlement moral : définition", texte: "Sont considérés comme harcèlement moral au travail tous gestes, paroles, écrits, comportements, attitudes répétées ou systématiques et abusifs qui ont pour objet ou pour effet une dégradation des conditions de travail portant atteinte aux droits et à la dignité du travailleur ou de l’employeur, d’altérer leur santé physique ou mentale ou de compromettre leur avenir professionnel.", resume: "Le harcèlement moral est constitué par des gestes, paroles, écrits, comportements ou attitudes répétés ou systématiques et abusifs qui dégradent les conditions de travail, portent atteinte aux droits et à la dignité, altèrent la santé ou compromettent l'avenir professionnel.", motsCles: ["harcèlement moral","définition","dignité","santé"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 12" },
  { id: "l24-13", numero: "13", loi: "2024-014", theme: "Principes, discrimination et harcèlement", titre: "Prévention de la violence et du harcèlement", texte: "L’employeur est tenu de prendre des mesures appropriées correspondant à son degré de contrôle pour prévenir la violence et le harcèlement dans le monde du travail. Une telle obligation inclut en particulier, dans la mesure où cela est raisonnable et pratiquement réalisable : 1. la définition et la mise en œuvre, en consultation avec les travailleurs et leurs représentants, d’une politique du lieu de travail relative à la violence et au harcèlement ; 2. la prise en compte de la violence et du harcèlement et des risques psychosociaux qui y sont associés, dans la gestion de la sécurité et de la santé au travail ; 3. l’identification des dangers et l’évaluation des risques de violence et de harcèlement, en y associant les travailleurs et leurs représentants, la prise de mesures destinées à prévenir et à maîtriser ces dangers et ces risques; 4. la mise à disposition des travailleurs et des autres personnes concernées, sous des formes accessibles selon le cas, d’informations et d’une formation sur les dangers et les risques de violence et de harcèlement identifiés et sur les mesures de prévention et de protection correspondantes, y compris sur les droits et responsabilités des travailleurs et autres personnes concernées en lien avec la politique visée à l’alinéa 2.1 du présent article ;", resume: "L'employeur doit prendre des mesures appropriées pour prévenir la violence et le harcèlement : politique du lieu de travail, prise en compte des risques psychosociaux, identification des risques, information et formation des travailleurs.", motsCles: ["prévention","harcèlement","violence","risques psychosociaux","formation"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 13" },
  { id: "l24-14", numero: "14", loi: "2024-014", theme: "Principes, discrimination et harcèlement", titre: "Signalement du harcèlement", texte: "L’employeur est tenu de mettre en place au sein de l’établissement: 1. une procédure appropriée permettant à la victime, aux témoins et aux dénonciateurs de signaler l’acte, dans le respect de la vie privée des personnes concernées et sans avoir à craindre des représailles ; 2. des mesures appropriées interdisant la violence et le harcèlement et les sanctionnant de manière appropriée, dans le respect du droit à la défense.", resume: "L'employeur doit mettre en place une procédure permettant à la victime, aux témoins et aux dénonciateurs de signaler les faits sans craindre de représailles, et des mesures interdisant et sanctionnant la violence et le harcèlement, dans le respect du droit à la défense.", motsCles: ["signalement","harcèlement","témoin","représailles","procédure"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 14" },
  { id: "l24-15", numero: "15", loi: "2024-014", theme: "Principes, discrimination et harcèlement", titre: "Droit des victimes de harcèlement", texte: "Toute victime de harcèlement est en droit de demander des dommages-intérêts auprès d’une juridiction compétente, qu’il soit travailleur ou employeur. Aucun travailleur ne peut faire l'objet d’une sanction ni d’une discrimination dans sa carrière ou dans son travail, ni d’un licenciement pour avoir résisté à des agissements de violence ou de harcèlement dans le monde du travail. Aucun travailleur ne peut faire l'objet d’une sanction ni d’une discrimination dans sa carrière ou dans son travail, ni d’un licenciement pour avoir dénoncé, témoigné ou relaté des actes de violence ou de harcèlement dans le monde du travail.", resume: "Toute victime de harcèlement (travailleur ou employeur) peut demander des dommages-intérêts à la juridiction compétente. Aucun travailleur ne peut être sanctionné, discriminé ou licencié pour avoir résisté, dénoncé ou témoigné.", motsCles: ["harcèlement","dommages-intérêts","victime","dénonciation","protection"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 15" },
  { id: "l24-16", numero: "16", loi: "2024-014", theme: "Principes, discrimination et harcèlement", titre: "Responsabilité de l'employeur en cas de harcèlement", texte: "L’employeur engage ses responsabilités lorsque les agissements étaient le fait d’un représentant de l’employeur ou de toute personne appartenant à l’établissement ou à l’entreprise et que l’employeur, informé par le travailleur victime ou par toute autre personne, n’a pas pris les mesures appropriées pour les faire cesser.", resume: "L'employeur engage sa responsabilité si, informé d'agissements de harcèlement commis par son représentant ou une personne de l'entreprise, il n'a pas pris les mesures appropriées pour les faire cesser.", motsCles: ["responsabilité","employeur","harcèlement","mesures"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 16" },
  { id: "l24-17", numero: "17", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Liberté contractuelle", texte: "Les contrats de travail sont passés librement, sous réserve du respect des dispositions d'ordre public et des bonnes mœurs. Ils sont soumis aux règles de droit commun, notamment le consentement des parties, la capacité de contracter, un objet certain et une cause licite.", resume: "Les contrats de travail sont passés librement, dans le respect de l'ordre public et des bonnes mœurs, selon les règles du droit commun (consentement, capacité, objet certain, cause licite).", motsCles: ["contrat","liberté","consentement"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 17" },
  { id: "l24-18", numero: "18", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Contrat écrit à l'embauche", texte: "Il est constaté au moment de l'embauche, par un écrit précisant au moins la fonction, la catégorie professionnelle, l'indice minimum de classification, le salaire du travailleur et la date d'effet du contrat. Il est rédigé en malagasy et/ou en français selon la convenance des parties. Il est établi en double exemplaire : le premier étant tenu par l'employeur tandis que le second doit être remis immédiatement au travailleur après signature des deux parties.", resume: "L'embauche est constatée par un écrit précisant au moins la fonction, la catégorie professionnelle, l'indice minimum de classification, le salaire et la date d'effet. Il est rédigé en malagasy et/ou en français, en double exemplaire, le second étant remis immédiatement au travailleur.", motsCles: ["contrat écrit","embauche","double exemplaire","salaire","catégorie"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 18" },
  { id: "l24-19", numero: "19", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Modèle de contrat", texte: "Le Ministère en charge du Travail et de l’emploi met à disposition du public un modèle pour chaque type de contrat de travail, comprenant les clauses impératives et substantielles devant y être inclues conformément aux articles 18 et 29 du présent Code. Ledit modèle servira de référence aux parties dans l’élaboration de leur contrat. Toutefois, la partie la plus diligente peut soumettre le contrat de travail à l’Inspecteur du travail et des lois sociales territorialement compétent pour un contrôle de conformité à priori ou à posteriori.", resume: "Le Ministère du Travail met à disposition un modèle pour chaque type de contrat. Chaque partie peut soumettre le contrat à l'inspecteur du travail pour un contrôle de conformité.", motsCles: ["modèle","contrat","inspecteur","conformité"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 19" },
  { id: "l24-20", numero: "20", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Absence de contrat écrit", texte: "En l'absence de contrat de travail écrit, l'existence d’une relation de travail fondée sur les critères des articles 2 et 3 peut être prouvée par tous les moyens.", resume: "Sans contrat écrit, l'existence d'une relation de travail peut être prouvée par tous les moyens.", motsCles: ["preuve","contrat oral","sans écrit"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 20" },
  { id: "l24-22", numero: "22", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Contrat à durée indéterminée ou déterminée", texte: "Le contrat de travail peut être conclu pour une durée indéterminée ou une durée déterminée.", resume: "Le contrat de travail peut être conclu pour une durée indéterminée (CDI) ou déterminée (CDD).", motsCles: ["CDI","CDD","contrat"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 22" },
  { id: "l24-23", numero: "23", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Définition du CDD", texte: "Un contrat à durée déterminée est un contrat de travail caractérisé, au moment de sa conclusion, par l'existence d'un terme fixé par les parties ou lié à un événement dont la survenance future est certaine même si elle ne dépend pas de la volonté des parties. Le contrat à durée déterminée doit être établi par écrit.", resume: "Le CDD a un terme fixé par les parties ou lié à un événement futur certain. Il doit être établi par écrit.", motsCles: ["CDD","terme","écrit"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 23" },
  { id: "l24-24", numero: "24", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Cas de recours au CDD", texte: "Seuls peuvent faire l'objet d'un contrat à durée déterminée les travaux qui n'entrent pas dans les activités normales et permanentes de l'établissement ou qui portent sur un ouvrage déterminé dont la réalisation constitue le terme du contrat. Néanmoins, le contrat de travail peut être conclu pour une durée déterminée dans les cas suivants : 1. les travailleurs engagés en complément d’effectif pour exécuter des travaux nés d’un surcroit extraordinaire de l’activité de l’entreprise ; 2. la réalisation de travaux urgents nécessités par des mesures de sécurité.", resume: "Un CDD n'est possible que pour des travaux qui n'entrent pas dans les activités normales et permanentes de l'établissement ou pour un ouvrage déterminé, ainsi que pour un surcroît extraordinaire d'activité ou des travaux urgents de sécurité.", motsCles: ["CDD","recours","surcroît","travaux urgents"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 24" },
  { id: "l24-25", numero: "25", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "CDD : durée, renouvellement et transformation en CDI", texte: "Un contrat à durée déterminée ne peut être conclu pour une durée supérieure à deux (02) ans, ni inférieure à un (01) mois. Ce même contrat peut être renouvelé deux fois, sans que la durée totale, renouvellement compris ne dépasse six (06) ans. Le contrat de travail à durée déterminée se transforme automatiquement en contrat de travail à durée indéterminée après deux renouvellements successifs. La réembauche au même poste d'un travailleur lié par un contrat à durée déterminée après une interruption ne dépassant pas trois (03) mois est considérée comme un renouvellement du contrat.", resume: "Un CDD dure de 1 mois à 2 ans. Il peut être renouvelé deux fois, la durée totale ne dépassant pas 6 ans, et se transforme automatiquement en CDI après deux renouvellements successifs. La réembauche au même poste après une interruption d'au plus 3 mois compte comme un renouvellement.", motsCles: ["CDD","renouvellement","durée","CDI","requalification","6 ans"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 25", equivalent: "cdd-duree" },
  { id: "l24-26", numero: "26", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "CDD : modalités fixées par voie réglementaire", texte: "Les modalités et les conditions d’exécution du contrat à durée déterminée seront fixées par voie réglementaire, en particulier en ce qui concerne les activités pouvant faire l’objet d’un contrat à durée déterminée ainsi que la priorité d’embauche sous contrat à durée indéterminée des salariés précédemment sous contrat à durée déterminée.", resume: "Les modalités et conditions d'exécution du CDD, notamment les activités concernées et la priorité d'embauche en CDI des anciens CDD, seront fixées par voie réglementaire.", motsCles: ["CDD","décret","priorité d'embauche"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 26" },
  { id: "l24-27", numero: "27", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Contrats réputés à durée indéterminée", texte: "Sont en particulier considérés conclus pour une durée indéterminée : 1. le contrat à durée déterminée dont les conditions exigées pour son existence ne sont pas remplies ; 2. le contrat à durée déterminée et le contrat d'essai au terme desquels aucune des parties n'a manifesté sa volonté de cesser la relation de travail ; 3. le contrat des journaliers occupés au même poste de façon intermittente pendant six (06) mois successifs pour le compte d'un même employeur et totalisant en moyenne vingt (20) jours de travail par mois. 4. Toute relation de travail sans contrat écrit, mais dont l’existence est prouvée.", resume: "Sont réputés CDI : le CDD dont les conditions ne sont pas remplies ; le CDD ou l'essai à l'issue duquel personne n'a manifesté sa volonté de cesser la relation ; les journaliers occupés au même poste 6 mois de suite avec en moyenne 20 jours par mois ; toute relation de travail sans écrit mais prouvée.", motsCles: ["CDI","requalification","CDD","journalier","sans écrit"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 27", equivalent: "cdd-requalification" },
  { id: "l24-28", numero: "28", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Activité en dehors du contrat, non-concurrence", texte: "Le travailleur engage ses services pour un employeur. Toutefois, il lui est loisible d'exercer, en-dehors de son temps de travail, toute activité à caractère professionnel non susceptible de concurrencer l'entreprise ou de nuire à la bonne exécution des services convenus. Est nulle de plein droit toute clause d'un contrat portant interdiction pour le travailleur d'exercer une activité quelconque à l'expiration du contrat, sans préjudice de l’obligation du salarié au secret professionnel vis-à-vis de son ex-employeur et sous peine d’une condamnation à des dommages intérêts solidairement avec le nouvel employeur. Toutefois, quel que soit le motif de la rupture du contrat, il est interdit au salarié inventeur de s'engager auprès d'un autre employeur exerçant la même activité, jusqu'à ce que l'invention créée ou en cours de création soit protégée par un brevet. L’interdiction est levée en cas de faillite de l'entreprise. En contrepartie de cette interdiction, à compter de la cessation de la relation de travail et jusqu’à ce que l’invention soit protégée par le brevet ou pour une durée fixée par accord des parties, il a droit à une prime ou indemnité mensuelle d’invention dont le montant est équivalent à un mois de salaire. Est considérée comme salarié inventeur toute personne dont le contrat de travail est régi par le Code du travail et qui réalise pour le compte de l’employeur une invention telle que définie par les lois et règlements régissant la propriété industrielle, ou y participe.", resume: "Le travailleur peut exercer une autre activité hors de son temps de travail si elle ne concurrence pas l'entreprise. Toute clause lui interdisant d'exercer une activité après la fin du contrat est nulle, sans préjudice du secret professionnel. Des règles spéciales existent pour le salarié inventeur.", motsCles: ["non-concurrence","clause","secret professionnel","inventeur"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 28" },
  { id: "l24-29", numero: "29", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Modification unilatérale du contrat", texte: "Les clauses substantielles d’un contrat individuel de travail, telles que la classification professionnelle, la rémunération et le poste occupé ne pourront faire l'objet d'une modification unilatérale moins favorable au travailleur. La rupture occasionnée par une modification unilatérale moins favorable des clauses substantielles du contrat de travail est imputable à l’employeur, dès lors que l’autre partie lui a fait savoir par écrit qu’elle a pris acte de la rupture.", resume: "Les clauses substantielles (classification, rémunération, poste) ne peuvent pas être modifiées unilatéralement de façon moins favorable au travailleur. Si le travailleur écrit qu'il prend acte de la rupture causée par une telle modification, la rupture est imputable à l'employeur.", motsCles: ["modification","clause substantielle","prise d'acte","salaire","poste"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 29" },
  { id: "l24-30", numero: "30", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Changement d'employeur", texte: "S'il survient une modification dans la situation juridique de l'employeur, notamment par succession, vente, fusion, transformation de fonds, mise en société, mise en concession, mise en location, tous les contrats de travail en cours au jour de la modification subsistent entre le nouvel employeur et le personnel de l'entreprise. Leur résiliation ne peut intervenir que dans les formes et conditions prévues par la Section 3 du présent Chapitre. La cessation d'activité de l'entreprise, sauf en cas de force majeure, ne dispense pas l'employeur de respecter les règles établies aux articles 43 à 46 de la présente loi. La faillite et la liquidation judiciaire ne sont pas considérées comme cas de force majeure.", resume: "En cas de vente, fusion, succession, etc., les contrats de travail en cours subsistent avec le nouvel employeur. La faillite et la liquidation judiciaire ne sont pas des cas de force majeure.", motsCles: ["transfert","vente","fusion","faillite","contrat maintenu"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 30" },
  { id: "l24-31", numero: "31", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Suspension du contrat de travail", texte: "Aucun employeur ne peut résilier le contrat de travail lorsqu'il se trouve suspendu. Le contrat est suspendu : 1. en cas de fermeture de l'Etablissement par suite du départ de l'employeur sous les drapeaux ou pour une période obligatoire d'instruction militaire ; 2. pendant la durée du service militaire du travailleur et pendant les périodes d'instruction militaire auxquelles il est astreint ; 3. pendant la durée d'absence du travailleur en cas de maladie nécessitant un arrêt de travail prolongé, dûment constatée par le service médical du travail ou, à défaut, par un Médecin agréé, laquelle durée est limitée à six (06) mois consécutifs. Passé ce délai, l’employeur peut rompre le contrat de travail, mais doit régler tous les droits du travailleur, dont notamment le préavis ; 4. pendant la durée d'absence du travailleur, dans la limite de deux (02) mois consécutifs, en cas de maladie ou d’hospitalisation d'un enfant au sens du Code de prévoyance sociale, sous réserve de la présentation d’un certificat médical justifiant la présence obligatoire du travailleur. Passé ce délai de deux mois, l’employeur peut rompre le contrat de travail, mais doit régler tous les droits du travailleur, dont notamment le préavis ; 5. pendant la durée d'absence du travailleur, dans la limite de quinze (15) jours consécutifs, en cas d’hospitalisation du conjoint ou de la conjointe légitime sous réserve de la présentation d’un certificat d’hospitalisation de l’intéressé ; 6. en cas de participation du travailleur à une compétition sportive nationale ou internationale, dûment attestée par le Ministère en charge des Sports et les fédérations respectives. 6.1. La durée de préparation, stage ou formation, de la compétition nationale ou internationale entre en compte dans la durée de suspension du contrat ; 6.2. Pour les sportifs qualifiés de haut niveau, les conditions prévues par les dispositions de la loi relative à l'organisation et à la promotion des activités physiques et sportives sont appliquées par la conclusion de conventions entre le Ministère en charge du Sport et les organismes publics ou privés concernés ; 7. pendant l'absence du travailleur appelé à des fonctions électives. Dans ce cas, la suspension du contrat de travail ne dépasse pas un mandat. Passé ce délai, l’employeur peut rompre le contrat de travail, mais doit régler tous les droits du travailleur, dont notamment le préavis ; 8. en cas de mise en chômage technique des travailleurs, dont la durée est limitée à six (06) mois consécutifs. 8.1. Le chômage technique se définit comme étant toute interruption collective du travail résultant de causes conjoncturelles, de nature technique, économique ou accidentelle telles que des accidents survenus aux matériels, une interruption de la force motrice, un sinistre, une pénurie accidentelle de matières premières, d’outillage et de moyens de transport ; 8.2. La déclaration de chômage technique se fait au préalable auprès de l’inspection du travail territorialement compétent, sauf cas de force majeure, en précisant le motif, la durée et la liste du personnel touché ; il appartient à l’employeur d’informer la Caisse Nationale de Prévoyance Sociale en parallèle ; 8.3. Toutefois, le travailleur peut rompre le contrat sans préavis après trois (03) mois ; 8.4. Sauf pour les motifs accidentels, la mise en chômage technique respecte l’ordre de priorité indiqué à l’article 48 de la présente loi. En cas de désaccord, l’Inspecteur du travail et des lois sociales du ressort est saisi par l’employeur et émet son avis dans les trois (03) jours ouvrables de sa saisine ; 8.5. Le chômage technique cesse dès la disparition du ou des motifs invoqués par l’employeur ; 8.6. Passé le délai de six mois, en l’absence de réintégration dans l’entreprise, le contrat est considéré comme rompu et l’employeur doit régler les droits du travailleur, dont notamment le préavis et l’indemnité de licenciement ; 8.7. Durant les situations de crises nationales ou régionales aiguës telles que celles résultant de pandémies ou de catastrophes naturelles, le Ministre chargé du Travail et de l’emploi peut prévoir par Arrêté pris après avis du Conseil National du Travail et de l’Emploi, une possibilité de prolongation exceptionnelle du chômage technique ne dépassant pas six mois. L’application de l’Arrêté est assurée par l’Inspecteur du travail et des lois sociales du ressort qui, à la réception de la demande de l’employeur, décide après s’être enquis de la situation dans l’entreprise ou l’établissement ; 9. durant la période d’arrêt de travail consécutive à un accident de travail ou à une maladie professionnelle ; 10.pendant la durée d'une grève licite ; 11.en cas de réquisition d'emploi prévue par la législation en vigueur ; 12.pendant la durée de la détention préventive du travailleur ayant bénéficié d'une décision judiciaire définitive de non-lieu, de relaxe ou d’acquittement pur et simple ou au bénéfice du doute ; 12.1. La réintégration du travailleur est, dans ce cas, obligatoire. 12.2. L’employeur est également tenu de réintégrer le travailleur ayant bénéficié d’une mise en liberté provisoire. La validité de cette réintégration est conditionnée par l’issue de la décision définitive. 12.3. Toutefois, l’employeur peut valablement licencier le travailleur si ce dernier a commis une faute professionnelle sans lien avec le Chef d’inculpation. 12.4. Si la détention se prolonge au-delà de 14 mois, l’employeur peut rompre le contrat de travail, mais doit régler tous les droits du travailleur dont notamment le préavis ; 13.pendant la durée de la mise en disponibilité du travailleur, dont les conditions et modalités sont fixées par la convention collective ou, à défaut, par l’accord individuel entre les deux parties.", resume: "L'employeur ne peut pas résilier un contrat suspendu. Cas de suspension : maladie constatée (6 mois consécutifs au plus), enfant malade ou hospitalisé (2 mois), hospitalisation du conjoint (15 jours), service militaire, compétition sportive, mandat électif, chômage technique (6 mois), accident du travail ou maladie professionnelle, grève licite, réquisition, détention préventive suivie de non-lieu ou relaxe, mise en disponibilité.", motsCles: ["suspension","maladie","accident du travail","chômage technique","6 mois","détention"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 31", equivalent: "suspension-contrat" },
  { id: "l24-32", numero: "32", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Indemnité de suspension", texte: "Dans les six premiers cas prévus à l’article 31 ci-dessus, l’employeur est tenu de verser au travailleur, pendant la durée de la suspension, une indemnité dénommée « indemnité de suspension », égale au montant de sa rémunération dans la limite de un (01) mois, si la durée normale du préavis est inférieure à ce délai et dans la limite normale du préavis dans les autres cas.", resume: "Dans les six premiers cas de suspension de l'article 31, l'employeur verse pendant la suspension une indemnité égale à la rémunération, dans la limite d'un mois si la durée normale du préavis est plus courte, et dans la limite de la durée normale du préavis dans les autres cas.", motsCles: ["indemnité de suspension","maladie","rémunération","préavis"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 32", equivalent: "indemnite-suspension" },
  { id: "l24-33", numero: "33", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Maladie de longue durée", texte: "Les travailleurs atteints d'une maladie de longue durée dont le traitement nécessite une période d’arrêt de travail de plus de six (06) mois, après avis du Médecin agréé, et dont la liste est fixée par Arrêté conjoint du Ministre chargé du Travail et du Ministre chargé de la Santé, perçoivent une indemnité dont les conditions et les modalités sont fixées par le Code de protection sociale et ses textes d’application.", resume: "Les travailleurs atteints d'une maladie de longue durée (arrêt de plus de 6 mois, liste fixée par arrêté conjoint Travail-Santé) perçoivent une indemnité dont les conditions sont fixées par le Code de protection sociale.", motsCles: ["maladie longue durée","indemnité","CNaPS","6 mois"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 33" },
  { id: "l24-34", numero: "34", loi: "2024-014", theme: "Formation et exécution du contrat", titre: "Suspension et représentants du personnel", texte: "La suspension du contrat de travail ne suspend pas les missions de représentant du personnel. Cependant, durant la période de suspension de leur contrat de travail, les représentants du personnel doivent informer l’employeur avant d’entrer dans l’enceinte de l’entreprise dans le cadre de l’exercice de leurs missions et dans le respect de validation de toute communication au personnel.", resume: "La suspension du contrat ne suspend pas les missions de représentant du personnel, qui doit toutefois informer l'employeur avant d'entrer dans l'entreprise.", motsCles: ["représentant","suspension","mission"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 34" },
  { id: "l24-35", numero: "35", loi: "2024-014", theme: "Rupture du contrat", titre: "Causes de rupture du CDI", texte: "Le contrat de travail à durée indéterminée est rompu pour quatre (04) causes : 1. du fait de l'employeur, par le licenciement ; 2. du fait du travailleur, par la démission ; 3. par accord de volontés des parties ; 4. en cas de force majeure laissée à l'appréciation de la juridiction compétente.", resume: "Le CDI est rompu : par le licenciement (employeur), par la démission (travailleur), par accord des parties, ou en cas de force majeure appréciée par la juridiction compétente.", motsCles: ["rupture","CDI","licenciement","démission","accord","force majeure"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 35" },
  { id: "l24-36", numero: "36", loi: "2024-014", theme: "Rupture du contrat", titre: "Rupture d'un CDD", texte: "Le contrat de travail à durée déterminée cesse de plein droit à l’échéance du terme. La suspension du contrat de travail à durée déterminée ne fait pas obstacle à l’échéance du terme. Le contrat de travail à durée déterminée ne peut cesser avant terme par la volonté d'une seule des parties que : 1. dans les cas prévus au contrat ; 2. dans les cas de faute lourde prévus dans le règlement intérieur ou, à défaut, laissés à l'appréciation de la juridiction compétente ; 3. en cas de force majeure, laquelle n’inclut pas les difficultés économiques et les mutations technologiques. Hors les exceptions prévues à l’alinéa premier du présent article, la rupture avant terme d’un contrat à durée déterminée, décidée unilatéralement, rend l’auteur débiteur, vis-à-vis de l’autre partie, d’une indemnité dont le montant correspond aux salaires et avantages qui auraient dû être perçus durant la période qui restait à courir.", resume: "Le CDD cesse à son terme. Avant le terme, une seule partie ne peut le rompre que dans les cas prévus au contrat, en cas de faute lourde, ou de force majeure (qui n'inclut pas les difficultés économiques). Sinon, l'auteur doit verser les salaires et avantages de la période restant à courir.", motsCles: ["CDD","rupture anticipée","faute lourde","force majeure","indemnité"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 36", equivalent: "cdd-rupture" },
  { id: "l24-37", numero: "37", loi: "2024-014", theme: "Rupture du contrat", titre: "Préavis et indemnité de préavis (CDI)", texte: "Le contrat à durée indéterminée peut cesser par la volonté de l'une des parties. Cette résiliation est subordonnée à un préavis donné par la partie qui prend l'initiative de la rupture. La rupture d'un contrat à durée indéterminée peut intervenir sans préavis en cas de faute lourde prévue dans le règlement intérieur ou, à défaut, laissée à l'appréciation de la juridiction compétente. Sauf en cas de faute lourde, toute rupture de contrat à durée indéterminée sans préavis ou sans que le délai de préavis ait été intégralement observé emporte obligation pour la partie ne l’ayant pas respecté de verser à l'autre partie une indemnité dont le montant correspond à la rémunération et aux avantages de toute nature dont aurait bénéficié le travailleur durant le délai de préavis qui n'aura pas été effectivement respecté. Toutefois, si le travailleur en fait expressément la demande, l’employeur peut le dispenser de tout ou partie du préavis.", resume: "La résiliation d'un CDI exige un préavis, sauf faute lourde prévue au règlement intérieur ou appréciée par le juge. Sans préavis ou préavis incomplet, la partie fautive verse la rémunération et les avantages correspondant au préavis non respecté. Le travailleur peut demander à être dispensé de tout ou partie du préavis.", motsCles: ["préavis","indemnité","faute lourde","licenciement","démission"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 37", equivalent: "preavis-indemnite" },
  { id: "l24-38", numero: "38", loi: "2024-014", theme: "Rupture du contrat", titre: "Durée du préavis : convention collective ou décret", texte: "En l’absence de dispositions plus favorables prévues par la convention collective, un Décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi détermine les conditions et la durée du préavis ainsi que les droits et obligations des deux parties en matière de préavis. Pendant la durée du préavis, l'employeur est tenu de délivrer au travailleur, à la date de la notification de la rupture, une attestation provisoire d'emploi sous peine de dommages intérêts.", resume: "Sauf dispositions plus favorables de la convention collective, un décret fixe les conditions et la durée du préavis. Pendant le préavis, l'employeur doit remettre dès la notification de la rupture une attestation provisoire d'emploi, sous peine de dommages-intérêts.", motsCles: ["préavis","durée","décret","attestation provisoire","convention collective"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 38", equivalent: "preavis-duree" },
  { id: "l24-39", numero: "39", loi: "2024-014", theme: "Rupture du contrat", titre: "Rupture abusive et dommages-intérêts", texte: "La rupture est abusive lorsqu'elle est effectuée sans motif légitime, sans cause réelle et sérieuse. Sont particulièrement abusifs les licenciements : 1. non conformes aux procédures définies par le présent Code du travail, par la convention collective ou par les règlements intérieurs ; 2. effectués sans raisons professionnelles valables ou assortis de motifs fallacieux ; 3. motivés par les opinions du travailleur ou son appartenance à un syndicat ; Outre les cas cités ci-dessus, il appartient au juge d'apprécier le caractère abusif ou non du licenciement. Toute rupture abusive du contrat de travail peut donner lieu à des dommages intérêts laissés à l'appréciation de la juridiction compétente. Il appartient à la partie auteur de la rupture d'établir que celle-ci est légitime.", resume: "Est abusive la rupture sans motif légitime ni cause réelle et sérieuse, notamment le licenciement non conforme aux procédures, sans raison professionnelle valable, ou motivé par les opinions ou l'appartenance syndicale. Les dommages-intérêts sont laissés au juge et c'est à l'auteur de la rupture de prouver qu'elle est légitime.", motsCles: ["licenciement abusif","dommages-intérêts","motif","preuve","syndicat"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 39", equivalent: "licenciement-abusif" },
  { id: "l24-40", numero: "40", loi: "2024-014", theme: "Rupture du contrat", titre: "Rupture pour violence ou harcèlement", texte: "Toute rupture du contrat de travail pour cause de violence ou de harcèlement sexuel ou moral est imputable à la partie auteur de l'acte. Il appartient à la partie requérante de fournir les preuves de l'acte par tous les moyens. La rupture pour cause de harcèlement sexuel ou moral peut donner lieu à la partie victime des dommages et intérêts fixés par la juridiction compétente à la charge de l'auteur de l'acte.", resume: "Toute rupture causée par la violence ou le harcèlement sexuel ou moral est imputable à son auteur. La partie qui l'invoque doit apporter les preuves par tous moyens, et la victime peut obtenir des dommages-intérêts à la charge de l'auteur.", motsCles: ["harcèlement","rupture","imputable","preuve","dommages-intérêts"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 40", equivalent: "harcelement-rupture" },
  { id: "l24-41", numero: "41", loi: "2024-014", theme: "Rupture du contrat", titre: "Notification écrite de la rupture", texte: "La partie qui prend l'initiative de rompre le contrat de travail doit notifier à l'autre partie sa décision écrite avec indication des motifs sur lesquels elle se fonde et la transmettre par tous les moyens probants à celle-ci. La date de réception de la lettre de licenciement ou de démission fixe le point de départ du préavis. Est irrecevable toute présentation de nouveau motif de rupture après la date de notification.", resume: "Celui qui rompt le contrat doit notifier sa décision par écrit avec les motifs, par un moyen probant. La réception de la lettre fait partir le préavis. Aucun nouveau motif ne peut être invoqué après la notification.", motsCles: ["notification","lettre de licenciement","motifs","démission","préavis"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 41", equivalent: "notification-rupture" },
  { id: "l24-42", numero: "42", loi: "2024-014", theme: "Rupture du contrat", titre: "Procédure de licenciement et droits du salarié", texte: "L'employeur envisageant de licencier un travailleur, en l'absence d'un conseil de discipline au sein de l'entreprise, doit respecter le droit à la défense de celui-ci, notamment par l'information écrite préalable de l'intéressé sur les motifs de licenciement et sa convocation à un entretien préalable, par la communication du dossier des faits reprochés s'il en fait la demande ainsi que par la présentation de ses moyens de défense et son assistance par une personne de son choix. La convocation à comparaître au conseil de discipline ou, à défaut, à l’entretien préalable au licenciement doit être notifiée au travailleur par tout écrit probant, au moins trois (03) jours ouvrables à l’avance, pour lui permettre de préparer ses moyens de défense de manière adéquate, compte tenu de la gravité des faits qui lui sont reprochés ou de toutes autres circonstances dans lesquelles le licenciement est envisagé. Si le travailleur refuse de recevoir la convocation ou tout document constitutif de la procédure de licenciement ou s’il ne se présente pas à l’entretien sans motif sérieux, il est réputé avoir renoncé à son droit à la défense. L’employeur est tenu de conserver les documents relatifs au licenciement pendant une période minimale de cinq ans. Le licenciement qui doit être notifié par écrit ouvre droit pour le travailleur : 1. au solde du salaire à la date de départ de l’entreprise ; 2. à l'indemnité compensatrice de congé non pris avant la rupture ; 3. à un préavis calculé conformément aux dispositions en vigueur, sauf en cas de faute lourde; 4. à la délivrance d'un certificat de travail. L’employeur est tenu de régler les droits visés à l’alinéa 5 ci-dessus dès la cessation de travail.", resume: "Avant tout licenciement, l'employeur informe le salarié par écrit des motifs et le convoque à un entretien préalable au moins 3 jours ouvrables à l'avance ; le salarié peut se faire assister et obtenir son dossier. Le licenciement notifié par écrit ouvre droit au solde de salaire, aux congés non pris, au préavis (sauf faute lourde) et au certificat de travail, payés dès la cessation du travail. L'employeur conserve les documents 5 ans.", motsCles: ["licenciement","procédure","entretien préalable","défense","convocation","droits"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 42", equivalent: "licenciement-formalites" },
  { id: "l24-43", numero: "43", loi: "2024-014", theme: "Rupture du contrat", titre: "Démission", texte: "Le salarié peut librement démissionner. Toutefois, il est tenu d’indiquer le motif de sa décision.", resume: "Le salarié peut librement démissionner, mais doit indiquer le motif de sa décision.", motsCles: ["démission","motif","salarié"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 43", equivalent: "demission" },
  { id: "l24-44", numero: "44", loi: "2024-014", theme: "Rupture du contrat", titre: "Licenciement pour motif économique : définition", texte: "Le licenciement pour motif économique est un licenciement provoqué par des difficultés économiques, des mutations technologiques ou des motifs d’organisation entrainant une suppression de poste. Il peut être collectif ou individuel.", resume: "Le licenciement économique est provoqué par des difficultés économiques, des mutations technologiques ou des motifs d'organisation entraînant une suppression de poste. Il peut être collectif ou individuel.", motsCles: ["licenciement économique","difficultés","suppression de poste","mutation technologique"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 44", equivalent: "eco-definition" },
  { id: "l24-45", numero: "45", loi: "2024-014", theme: "Rupture du contrat", titre: "Licenciement économique : procédure", texte: "Les licenciements collectifs et individuels pour motif économique doivent suivre la procédure ci-après : 1. l’employeur doit au préalable consulter le comité d’entreprise et/ou, à défaut, les délégués du personnel sur la mesure projetée et leur fournir tous les renseignements sur les motifs, la situation financière de l’entreprise, le plan de redressement projeté, la liste du personnel concerné par catégorie professionnelle, la priorité de réembauche et l’évolution de l’emploi dans l’entreprise ; 2. un procès-verbal est établi à l'issue de cette réunion, qui fait par la suite l'objet d'affichage à l'intention du personnel de l'entreprise ; 3. dans les vingt (20) jours qui suivent, le comité d’entreprise et/ou les délégués du personnel se prononcent sur la mesure projetée et donnent leur avis ; 4. l’Inspecteur du travail et des lois sociales est saisi obligatoirement à la diligence de l’employeur qui doit joindre à sa demande le procès-verbal de consultation contenant l’avis du comité d’entreprise et/ou des délégués du personnel, ainsi que la liste du personnel touché par le licenciement et toutes autres pièces nécessaires. Il émet son avis dans les quinze (15) jours ouvrables qui suivent la saisine. En l’absence du comité d’entreprise ou des délégués du personnel, l’Inspecteur du travail et des lois sociales est saisi obligatoirement à la diligence de l’employeur sur la mesure projetée. Il émet son avis dans les quinze (15) jours ouvrables qui suivent la saisine.", resume: "Pour tout licenciement économique (collectif ou individuel) : consultation préalable du comité d'entreprise ou des délégués, procès-verbal affiché, avis sous 20 jours, puis saisine obligatoire de l'inspecteur du travail qui répond sous 15 jours ouvrables.", motsCles: ["licenciement économique","procédure","comité d'entreprise","inspecteur","délégués"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 45", equivalent: "eco-procedure" },
  { id: "l24-46", numero: "46", loi: "2024-014", theme: "Rupture du contrat", titre: "Licenciement économique : liste et ordre des départs", texte: "La liste du personnel touché par le licenciement collectif pour motif économique doit être établie par l'employeur en consultation avec les délégués du personnel. Elle doit respecter, par catégorie professionnelle, un ordre de licenciement conforme aux stipulations du plan social convenu en la matière dans le cadre de la convention collective ou, à défaut, tenant compte par ordre de priorité : 1. de l'ancienneté de service dans l'entreprise ; 2. des valeurs professionnelles, des compétences techniques et de la conscience professionnelle ; 3. des charges de famille. En cas de désaccord entre les deux parties sur la liste du personnel touché par la mesure projetée, l'Inspecteur du travail et des lois sociales décide, en application de ces critères, dans les quinze (15) jours ouvrables qui suivent sa saisine. Passé ce délai, le silence de l’Inspecteur du travail et des lois sociales vaut approbation de la liste.", resume: "La liste du personnel touché est établie avec les délégués, par catégorie professionnelle, selon le plan social ou, à défaut, l'ancienneté, les compétences et les charges de famille. L'inspecteur tranche en cas de désaccord ; son silence vaut approbation.", motsCles: ["liste","ordre des licenciements","ancienneté","charges de famille"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 46", equivalent: "eco-liste" },
  { id: "l24-47", numero: "47", loi: "2024-014", theme: "Rupture du contrat", titre: "Modification du contrat pour motif économique", texte: "Les difficultés économiques et la mutation technologique justifient également des modifications des clauses substantielles du contrat de travail. La modification des clauses substantielles du contrat pour motif économique se conforme aux procédures ci-après : 1. les modifications sont notifiées par écrit au travailleur concerné à la diligence de l'employeur ; 2. le travailleur doit émettre son avis, par écrit, dans un délai de quinze (15) jours à compter de la date de la réception de la lettre de notification ; 3. passé ce délai, le silence du travailleur vaut acceptation des novations apportées au contrat. Il en est de même si le travailleur a manifesté à temps sa volonté d'accepter les modifications ; 4. la rupture du contrat est imputable à l'employeur si le travailleur refuse les novations proposées et ce dernier bénéficie des droits accordés aux travailleurs licenciés pour motif économique.", resume: "Les difficultés économiques peuvent justifier des modifications du contrat, notifiées par écrit. Le travailleur répond sous 15 jours ; son silence vaut acceptation. S'il refuse, la rupture est imputée à l'employeur et il a les droits du licenciement économique.", motsCles: ["modification","motif économique","15 jours","refus"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 47", equivalent: "eco-individuel" },
  { id: "l24-48", numero: "48", loi: "2024-014", theme: "Rupture du contrat", titre: "Indemnité de licenciement économique", texte: "Sauf dispositions plus favorables du contrat individuel ou de la convention collective, tout travailleur licencié pour motif économique ou pour cessation d'activité de l'entreprise bénéficie d'une indemnité de licenciement calculée à raison de dix (10) jours de salaire par année complète de service, sans que le total puisse excéder six (06) mois de salaire. Cette indemnité, calculée sur la base du dernier taux de rémunération lors du licenciement, compte tenu de tous les avantages et accessoires n'ayant pas le caractère de remboursement de frais, ne se confond pas avec l'indemnité de préavis, ni avec l'indemnité compensatrice de congé payé, ni avec les dommages intérêts pour licenciement abusif.", resume: "Tout travailleur licencié pour motif économique ou cessation d'activité a droit à une indemnité de 10 jours de salaire par année complète de service, plafonnée à 6 mois de salaire, calculée sur le dernier taux de rémunération. Elle s'ajoute au préavis, aux congés payés et aux dommages-intérêts.", motsCles: ["indemnité de licenciement","10 jours","6 mois","ancienneté","économique"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 48", equivalent: "indemnite-licenciement" },
  { id: "l24-50", numero: "50", loi: "2024-014", theme: "Rupture du contrat", titre: "Certificat de travail", texte: "L'employeur doit obligatoirement, à la cessation du contrat de travail, délivrer au travailleur, sous peine de dommages intérêts, un certificat de travail indiquant exclusivement la date de son entrée, celle de son départ, la nature de l'emploi ou des emplois successivement occupés, les périodes pendant lesquelles ces emplois ont été tenus et les catégories professionnelles correspondantes. Pendant la durée du préavis, l'attestation provisoire d'emploi prévue à l'article 38 alinéa 2 de la présente loi, comportant les énonciations prévues à l'alinéa ci-dessus, doit être délivrée au travailleur sous peine de dommages intérêts. Le certificat et l'attestation sont exempts de tout droit de timbre et d'enregistrement.", resume: "À la fin du contrat, l'employeur remet un certificat de travail indiquant uniquement les dates d'entrée et de départ, les emplois occupés, les périodes et les catégories professionnelles, sous peine de dommages-intérêts. Pendant le préavis, une attestation provisoire d'emploi est due.", motsCles: ["certificat de travail","attestation","fin de contrat","dommages-intérêts"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 50", equivalent: "certificat-travail" },
  { id: "l24-51", numero: "51", loi: "2024-014", theme: "Rupture du contrat", titre: "Passation", texte: "A la cessation du contrat de travail, le travailleur est tenu de procéder à la passation à la personne et à la date que l’employeur doit lui indiquer à cette fin. La date de la passation ne doit pas être ultérieure à la dernière journée de travail, compte tenu, le cas échéant, de la période de préavis. En cas de défaillance du travailleur quant à son obligation de passation, l’employeur lésé peut demander des dommages intérêts auprès du Tribunal du travail.", resume: "À la fin du contrat, le travailleur doit faire la passation à la personne et à la date indiquées par l'employeur, au plus tard le dernier jour de travail. À défaut, l'employeur peut demander des dommages-intérêts au tribunal du travail.", motsCles: ["passation","fin de contrat","démission"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 51" },
  { id: "l24-52", numero: "52", loi: "2024-014", theme: "Période d'essai", titre: "L'essai doit être écrit", texte: "L’engagement ainsi que le renouvellement de l’engagement à l’essai doivent être constatés au moment de l’engagement par un accord écrit précisant au moins le poste à pourvoir, la durée, le salaire et la catégorie professionnelle. Dans tout contrat à durée déterminée ou indéterminée, l’essai non stipulé par écrit est réputé inexistant.", resume: "L'engagement et son renouvellement doivent être constatés par un accord écrit précisant au moins le poste, la durée, le salaire et la catégorie. Dans tout contrat, l'essai non stipulé par écrit est réputé inexistant.", motsCles: ["essai","écrit","période d'essai","renouvellement"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 52", equivalent: "essai-ecrit" },
  { id: "l24-53", numero: "53", loi: "2024-014", theme: "Période d'essai", titre: "Période d'essai : durée", texte: "La durée de l’essai est fonction de la catégorie professionnelle et ne doit pas dépasser le temps nécessaire pour que l’employeur apprécie l’aptitude professionnelle du travailleur. En tout état de cause, le contrat d’engagement à l’essai ne peut pas excéder six (06) mois, renouvelable une fois. Un Décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi détermine la forme et les modalités du contrat d'engagement à l'essai ainsi que sa durée tenant compte de la catégorie professionnelle, tel que le stipule le premier alinéa du présent article.", resume: "La durée de l'essai dépend de la catégorie professionnelle et ne doit pas dépasser le temps nécessaire pour apprécier le travailleur. L'essai ne peut excéder 6 mois, renouvelable une fois. Un décret précise la forme, les modalités et la durée selon la catégorie.", motsCles: ["essai","6 mois","renouvelable","décret","durée"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 53", equivalent: "periode-essai" },
  { id: "l24-54", numero: "54", loi: "2024-014", theme: "Période d'essai", titre: "Essai : mêmes conditions que les confirmés", texte: "Le travailleur engagé à l’essai bénéficie des mêmes conditions de travail et de protection sociale que les travailleurs confirmés au même poste.", resume: "Le travailleur à l'essai bénéficie des mêmes conditions de travail et de protection sociale que les travailleurs confirmés au même poste.", motsCles: ["essai","conditions de travail","protection sociale"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 54" },
  { id: "l24-55", numero: "55", loi: "2024-014", theme: "Période d'essai", titre: "Rupture pendant l'essai", texte: "Les dispositions des articles 29, 33, 35 et 37 du présent Code ne s'appliquent pas à l'engagement à l'essai, sauf convention contraire et sans que l'une ou l'autre des parties puisse prétendre à une indemnité.", resume: "Les articles 29, 33, 35 et 37 ne s'appliquent pas à l'essai, sauf convention contraire, et aucune partie ne peut prétendre à une indemnité.", motsCles: ["essai","rupture","préavis","indemnité"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 55", equivalent: "essai-rupture" },
  { id: "l24-56", numero: "56", loi: "2024-014", theme: "Période d'essai", titre: "Maladie pendant l'essai", texte: "Le contrat d'engagement à l'essai est suspendu pendant la durée d'absence du travailleur en cas de maladie dûment constatée par un Médecin agréé, durée limitée à la période d'essai restant à courir. Pendant la durée de suspension, l'employeur est tenu de verser au travailleur dans la limite d'un (01) mois une indemnité égale au montant de sa rémunération. A l'expiration de la suspension, l'engagement à l'essai est prorogé pour une durée correspondant à la durée de l'essai qui restait à courir avant la suspension.", resume: "L'essai est suspendu pendant une maladie constatée par un médecin agréé, dans la limite de la période d'essai restant à courir ; l'employeur verse la rémunération dans la limite d'un mois. L'essai est ensuite prorogé de la durée restant à courir.", motsCles: ["essai","maladie","suspension","prorogation"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 56" },
  { id: "l24-57", numero: "57", loi: "2024-014", theme: "Période d'essai", titre: "Abus en matière d'essai", texte: "L’Inspecteur du travail et des lois sociales est habilité à constater tout abus dans le domaine de l’essai, et à prendre toutes les mesures prévues à cet effet dont l’étendue est fixée par voie réglementaire.", resume: "L'inspecteur du travail peut constater tout abus en matière d'essai et prendre les mesures prévues par voie réglementaire.", motsCles: ["essai","abus","inspecteur"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 57", equivalent: "essai-abus" },
  { id: "l24-59", numero: "59", loi: "2024-014", theme: "Formes particulières d'emploi et télétravail", titre: "Travailleur migrant : définition", texte: "Le travailleur migrant est celui qui, pour l'accomplissement du travail convenu, va exercer, exerce ou a exercé une activité rémunérée dans un Etat dont il n’est pas ressortissant. Le terme travailleur migrant désigne aussi bien le travailleur émigré que le travailleur immigré. Au sens de la présente loi, en sont exclus les employés des organisations internationales et des missions diplomatiques, les apatrides, les réfugiés, les étudiants et les stagiaires. Tout traitement discriminatoire fondé sur un ou plusieurs des critères visés à l’article 7 ci-dessus est interdit.", resume: "Le travailleur migrant exerce une activité rémunérée dans un État dont il n'est pas ressortissant (émigré ou immigré). Tout traitement discriminatoire fondé sur les motifs de l'article 7 est interdit.", motsCles: ["migrant","émigré","immigré","discrimination"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 59" },
  { id: "l24-60", numero: "60", loi: "2024-014", theme: "Formes particulières d'emploi et télétravail", titre: "Travailleur émigré : contrat visé", texte: "Le contrat de travail du travailleur émigré doit faire l’objet d’un visa préalable d’un Inspecteur du travail et des lois sociales du service de la migration auprès du Ministère en charge du Travail et de l’emploi. La demande de visa du contrat de travail du travailleur émigré incombe à l’employeur. Le contrat de travail doit au moins stipuler que le travailleur émigré est soumis aux législations du travail et de la sécurité sociale du lieu d’emploi. Il doit également préciser les conditions de logement, d’accès à la justice et d’autres mécanismes de plaintes, de retour/rapatriement ainsi que de la prise en charge des frais de voyage quel que soit le motif de rupture du contrat évoqué. Avant l’exécution du contrat de travail, le travailleur émigré doit être soumis à une visite médicale tenant compte du poste de travail, auprès du service médical du travail ou, à défaut, d’un établissement sanitaire public. La visite médicale se fait à la demande de l’employeur. Les formes et modalités d’établissement du contrat de travail des travailleurs émigrés ainsi que les conditions et procédure de sortie du territoire d’un travailleur émigré sont fixés par voie réglementaire après avis du Conseil National du Travail et de l’Emploi.", resume: "Le contrat du travailleur malgache qui part travailler à l'étranger doit être visé par un inspecteur du travail du service de la migration. Il doit préciser notamment le logement, l'accès à la justice, le rapatriement et les frais de voyage, et être précédé d'une visite médicale.", motsCles: ["émigré","contrat","visa","étranger","rapatriement"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 60" },
  { id: "l24-61", numero: "61", loi: "2024-014", theme: "Formes particulières d'emploi et télétravail", titre: "Travailleur étranger à Madagascar : visa et permis de travail", texte: "Les travailleurs immigrés salariés ou bénévoles, ainsi que les volontaires internationaux en entreprise peuvent occuper un emploi à Madagascar à condition d’obtenir: 1. le visa préalable de leur contrat de travail par l’Inspecteur du travail et des lois sociales du service compétent auprès du Ministère en charge du Travail et de l’emploi ; 2. et le permis de travail délivré par le Ministre chargé du Travail ou par délégation de signature au Directeur Général du Travail et des Lois Sociales. Le permis de travail doit indiquer au moins l’identité du travailleur salarié ou bénévole, la nationalité, le poste occupé, la catégorie professionnelle, la validité et le lieu de travail. Les formes et modalités d’établissement, d’octroi et de retrait du permis de travail ainsi que les frais de traitement du dossier sont fixés par voie réglementaire après avis du Conseil National du Travail et de l’Emploi. Les conditions et les modalités d’autorisation des activités d’intermédiaires dans le recrutement et le placement des travailleurs immigrés salariés ou bénévoles sont fixés par voie réglementaire après avis du Conseil National du Travail et de l’Emploi.", resume: "Les travailleurs immigrés (salariés, bénévoles, volontaires internationaux) doivent obtenir le visa préalable de leur contrat par l'inspecteur du travail et un permis de travail délivré par le Ministre du Travail ou par délégation.", motsCles: ["permis de travail","étranger","immigré","visa"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 61" },
  { id: "l24-64", numero: "64", loi: "2024-014", theme: "Formes particulières d'emploi et télétravail", titre: "Travail à temps partiel", texte: "Est considéré comme salarié à temps partiel le travailleur dont la durée hebdomadaire de travail est inférieure à la durée légale pour la même période. Les droits du travailleur résultant de la durée du travail, tels que la rémunération, le droit au congé, l’allocation ou l’indemnité de congé, le préavis sont calculés au prorata du temps de travail effectif. Le contrat de travail doit faire mention de la durée de travail assignée au travailleur.", resume: "Est à temps partiel le travailleur dont la durée hebdomadaire est inférieure à la durée légale. Rémunération, congé, allocation de congé et préavis sont calculés au prorata. Le contrat mentionne la durée de travail.", motsCles: ["temps partiel","prorata","durée hebdomadaire"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 64" },
  { id: "l24-65", numero: "65", loi: "2024-014", theme: "Formes particulières d'emploi et télétravail", titre: "Travailleur journalier", texte: "Est considéré comme travailleur journalier, tout travailleur engagé de façon intermittente pour travailler journellement. Le contrat des journaliers occupés au même poste de façon intermittente pendant six (06) mois successifs pour le compte d'un même employeur et totalisant en moyenne vingt (20) jours de travail par mois est transformé en contrat à durée indéterminée. Le contrat des journaliers occupés au même poste de façon intermittente pendant cinq (05) ans successifs pour le compte d'un même employeur, mais n’atteignant pas la moyenne de vingt (20) jours de travail prévu au deuxième alinéa du présent article est transformé en contrat à durée indéterminée à temps partiel, dans les conditions visées à l’article 64 ci-dessus. Les autres conditions et modalités d’emploi d’un travailleur journalier sont précisées par voie règlementaire.", resume: "Le journalier est engagé de façon intermittente. Occupé au même poste 6 mois de suite avec en moyenne 20 jours par mois, son contrat devient un CDI. Après 5 ans sans atteindre cette moyenne, il devient un CDI à temps partiel.", motsCles: ["journalier","CDI","20 jours","5 ans"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 65" },
  { id: "l24-70", numero: "70", loi: "2024-014", theme: "Formes particulières d'emploi et télétravail", titre: "Télétravail : définition", texte: "Le télétravail, qu’il soit permanent ou ponctuel, s’entend de l’exécution du travail hors des locaux de l'employeur, par le recours aux technologies de l'information et de la communication. Il peut être fait recours au télétravail, soit dès la conclusion du contrat de travail, soit au cours de son exécution.", resume: "Le télétravail, permanent ou ponctuel, est le travail exécuté hors des locaux de l'employeur grâce aux technologies de l'information et de la communication. Il peut être prévu dès l'embauche ou en cours de contrat.", motsCles: ["télétravail","définition","travail à distance"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 70" },
  { id: "l24-71", numero: "71", loi: "2024-014", theme: "Formes particulières d'emploi et télétravail", titre: "Télétravail : cadre juridique", texte: "Le recours au télétravail est prévu soit par la convention collective ou l’accord d’Etablissement soit, à défaut, par le contrat de travail ou son avenant intervenant en cours d’exécution.", resume: "Le recours au télétravail est prévu par la convention collective ou l'accord d'établissement, ou à défaut par le contrat de travail ou un avenant.", motsCles: ["télétravail","contrat","avenant","convention collective"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 71" },
  { id: "l24-72", numero: "72", loi: "2024-014", theme: "Formes particulières d'emploi et télétravail", titre: "Télétravail : conditions à fixer par accord", texte: "Sous réserve du respect des lois et règlements en vigueur, les parties fixent par accord entre elles, dans le cadre des dispositions de l’article 71 ci-dessus, les conditions : 1. d'acceptation par le salarié des conditions de mise en œuvre du télétravail ; 2. de mise à disposition du travailleur des fournitures, du matériel et des équipements de travail ; 3. de contrôle du temps de travail ou de régulation de la charge de travail ; 4. de détermination des plages horaires durant lesquelles l'employeur peut habituellement contacter le salarié en télétravail.", resume: "Les parties fixent par accord les conditions d'acceptation par le salarié, de mise à disposition du matériel, de contrôle du temps de travail ou de la charge de travail, et les plages horaires où l'employeur peut le contacter.", motsCles: ["télétravail","matériel","horaires","contrôle"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 72" },
  { id: "l24-73", numero: "73", loi: "2024-014", theme: "Formes particulières d'emploi et télétravail", titre: "Télétravail : obligations de l'employeur", texte: "L’employeur est tenu : 1. d'informer le salarié, des règles relatives à l'usage du matériel informatique et de la communication électronique et des sanctions y correspondantes ; 2. d'organiser, suivant une périodicité raisonnable compte tenu de données telles que la durée fixée ou probable du recours au télétravail, un entretien qui porte notamment sur les conditions d'activité du salarié et sa charge de travail.", resume: "L'employeur doit informer le salarié des règles d'usage du matériel informatique et des sanctions, et organiser régulièrement un entretien sur ses conditions d'activité et sa charge de travail.", motsCles: ["télétravail","entretien","charge de travail","matériel"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 73" },
  { id: "l24-74", numero: "74", loi: "2024-014", theme: "Formes particulières d'emploi et télétravail", titre: "Télétravail en situation exceptionnelle", texte: "Dans les situations exceptionnelles rendant impossible l’exécution du travail dans les locaux de l’employeur, telles que les périodes d’épidémie, l’employeur peut décider du recours au télétravail dans le cadre de son pouvoir d’organisation. Dans les situations visées à l’alinéa premier du présent article, les parties fixent par accord entre elles les conditions de passage en télétravail et de retour à une exécution du contrat de travail sans télétravail. En tout état de cause, l’employeur est tenu de donner priorité au télétravailleur pour le retour à une exécution du contrat de travail sans télétravail lorsque la situation le permet.", resume: "En cas de situation exceptionnelle (épidémie par exemple) rendant impossible le travail dans les locaux, l'employeur peut décider le télétravail. Les conditions du passage et du retour sont fixées par accord, et le télétravailleur a priorité pour le retour.", motsCles: ["télétravail","épidémie","situation exceptionnelle","retour"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 74" },
  { id: "l24-83", numero: "83", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Égalité de rémunération", texte: "A travail égal et exigeant des niveaux égaux de qualifications ou à travail accompli dans des conditions égales ou à travail de nature différente mais néanmoins de valeur égale, la rémunération est égale pour tous les travailleurs, sans discrimination d’aucune sorte basée sur un ou plusieurs des motifs énumérés à l’article 7 de la présente loi. Le terme rémunération comprend le salaire ou traitement de base ou minimum et tous autres avantages, payés directement ou indirectement, en espèces ou en nature, par l'employeur au travailleur en raison de l'emploi de ce dernier. Les différences de rémunération basées sur les compétences, les performances et la valeur professionnelle objectivement mesurées ne constituent pas une violation de la règle stipulée à l’alinéa premier du présent article. Le système d’évaluation objective des emplois, comprenant en particulier la méthodologie et les critères d’évaluation est fixé par Décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi.", resume: "À travail égal, ou de valeur égale, la rémunération est égale pour tous sans discrimination. Les différences fondées sur les compétences, performances et valeur professionnelle objectivement mesurées sont permises.", motsCles: ["égalité de salaire","rémunération","discrimination","valeur égale"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 83", equivalent: "salaire-egal" },
  { id: "l24-84", numero: "84", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Absence et salaire", texte: "Le salaire étant la contrepartie du travail fourni, aucun salaire n'est dû en cas d'absence, en-dehors des cas prévus par la réglementation et sauf accord écrit entre les parties intéressées.", resume: "Le salaire étant la contrepartie du travail, aucun salaire n'est dû en cas d'absence, sauf cas prévus par la réglementation et sauf accord écrit entre les parties.", motsCles: ["absence","salaire","retenue"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 84", equivalent: "absence-salaire" },
  { id: "l24-85", numero: "85", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Salaire minimum d'embauche (SME)", texte: "Il est institué un salaire minimum agricole et non agricole d'embauche, en abrégé SME, prenant en considération le minimum vital pour les travailleurs et leur assurant un pouvoir d'achat suffisant. Un Décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi fixe le salaire minimum d’embauche par catégorie professionnelle, révisé périodiquement compte tenu de l'évolution des comptes de la Nation, de la conjoncture économique et des prix à la consommation. Un Décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi fixe les indices, la valeur du point d'indice et les salaires minima d'embauche et d'ancienneté par catégorie professionnelle applicables dans les secteurs agricoles et non agricoles. La fixation des salaires minima prévus aux alinéas 1 à 3 du présent article prend en considération les résultats des négociations salariales passées entre les organisations représentatives d’employeurs et de travailleurs au niveau national, lorsque de telles négociations ont lieu.", resume: "Un salaire minimum d'embauche agricole et non agricole est institué. Un décret fixe le SME par catégorie professionnelle, les indices, la valeur du point et les minima d'embauche et d'ancienneté, et le révise périodiquement.", motsCles: ["SME","salaire minimum","décret","catégorie"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 85", equivalent: "salaire-minimum" },
  { id: "l24-86", numero: "86", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Mensualisation", texte: "Les travailleurs payés à l'heure ou à la journée sont appointés au mois après six (06) mois de service continu dans la même entreprise.", resume: "Les travailleurs payés à l'heure ou à la journée sont payés au mois après 6 mois de service continu dans la même entreprise.", motsCles: ["mensualisation","heure","journée","6 mois"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 86" },
  { id: "l24-87", numero: "87", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Rémunération à la tâche, au rendement, « target »", texte: "La rémunération du travail à la tâche, aux pièces ou au rendement ainsi que la fixation des objectifs ou « targets » doivent se faire sur la base des paramètres objectifs liés à la nécessité de la production. La rémunération au rendement et les « targets » doivent être déterminés de telle sorte qu'ils procurent au travailleur de capacité moyenne et travaillant normalement un salaire au moins égal à celui du travailleur rémunéré au temps effectuant un travail analogue. Pour l’application des alinéas précédents : - « objectif » ou « target » désigne la production que le travailleur doit réaliser en un temps déterminé ; - « travailleur de capacité moyenne » désigne le travailleur dont la productivité catégorisée par l'activité correspond à la productivité moyenne des travailleurs de l'établissement, de l'entreprise, du secteur ou de la branche d'activité. Les taux minima des salaires, les informations sur les conditions de rémunération au rendement, sur le « target », ainsi que sur les paramètres objectifs de leur fixation doivent être apposés par l’employeur, dans un délai raisonnable, au bureau de l’employeur, au tableau d’affichage du lieu de travail et aux lieux de paye du personnel. En cas de litige, une commission paritaire d’arbitrage composée des représentants de l’employeur, des délégués du personnel et des délégués syndicaux et/ou des représentants des travailleurs inclus dans le travail à définir fixe et décide les paramètres objectifs et les informations visés à l’alinéa précédent. L’Inspecteur du travail et des lois sociales du ressort saisi par la partie la plus diligente assure l’arbitrage en cas de désaccord entre les parties sur la fixation de la rémunération au rendement et des « targets». En tout état de cause, le salaire minimum de sa catégorie professionnelle doit au moins être garanti au travailleur rémunéré à la tâche, aux pièces ou au rendement ou sur la base des « targets ».", resume: "La rémunération à la tâche, aux pièces ou au rendement et les objectifs doivent reposer sur des paramètres objectifs et procurer au travailleur de capacité moyenne au moins le salaire d'un travailleur payé au temps pour un travail analogue. Les taux et paramètres sont affichés.", motsCles: ["rendement","target","tâche","pièces","objectif"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 87" },
  { id: "l24-88", numero: "88", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Commissions et primes dans le calcul des indemnités", texte: "Lorsque la rémunération est constituée en tout ou en partie par des commissions ou des primes ou des prestations diverses, ou des indemnités représentatives de ces prestations, dans la mesure où elles ne constituent pas un remboursement de frais, il en est tenu compte pour le calcul de la rémunération pendant la durée du congé payé et de l’indemnité compensatrice de congé, de l'indemnité de préavis, de l'indemnité de licenciement, des dommages intérêts. Le montant à prendre en considération à ce titre est la moyenne mensuelle des éléments visés à l'alinéa précédent. Toutefois, la période sur laquelle s'effectue ce calcul n’excède pas les douze (12) mois de service ayant précédé la cessation du travail.", resume: "Les commissions, primes et prestations diverses (hors remboursement de frais) sont prises en compte, sur la moyenne mensuelle des 12 derniers mois de service, pour le calcul du congé, de l'indemnité de préavis, de licenciement et des dommages-intérêts.", motsCles: ["commission","prime","moyenne","12 mois","calcul"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 88" },
  { id: "l24-90", numero: "90", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Poste de niveau supérieur", texte: "Tout travailleur qui accède à un poste de niveau professionnel supérieur perçoit la rémunération correspondant à ses nouvelles fonctions.", resume: "Tout travailleur qui accède à un poste de niveau professionnel supérieur perçoit la rémunération correspondant à ses nouvelles fonctions.", motsCles: ["promotion","poste supérieur","rémunération"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 90" },
  { id: "l24-91", numero: "91", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Paiement en monnaie légale", texte: "Tout salaire doit être entièrement versé à Madagascar en monnaie ayant cours légal. Est interdit le paiement du salaire en alcool, en boisson alcoolisée ou en produits illicites.", resume: "Tout salaire est entièrement versé à Madagascar en monnaie ayant cours légal. Le paiement en alcool, boisson alcoolisée ou produits illicites est interdit.", motsCles: ["monnaie","Ariary","paiement","alcool"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 91" },
  { id: "l24-94", numero: "94", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Paiement du salaire : périodicité et délais", texte: "Le salaire de tout travailleur, quel que soit son mode de rémunération, doit être payé à intervalles réguliers, soit à la journée, soit à la semaine, soit à la quinzaine, soit au mois. Les retards de paiement doivent être justifiés par la force majeure. Nonobstant un retard justifié, le salaire doit être payé au plus tard au huitième (08) jour si le travailleur est payé à la journée ou à la semaine, au vingtième jour si le travailleur est payé à la quinzaine et huit (08) jours après l’échéance mensuelle si le travailleur est payé au mois. Sans préjudice des sanctions pénales y correspondantes, tout retard non justifié du paiement du salaire donne lieu à majoration selon le taux d’intérêt légal en vigueur. Un Arrêté du Ministre chargé du Travail et de l’emploi fixe les formes et modalités de paiement du salaire.", resume: "Le salaire est payé à intervalles réguliers (jour, semaine, quinzaine ou mois). Les retards doivent être justifiés par la force majeure. Au plus tard : 8e jour pour la journée ou la semaine, 20e jour pour la quinzaine, 8 jours après l'échéance pour le mois. Tout retard non justifié donne lieu à majoration au taux d'intérêt légal.", motsCles: ["salaire","retard","paiement","8 jours","intérêt légal"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 94", equivalent: "salaire-paiement" },
  { id: "l24-95", numero: "95", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Bulletin de paie", texte: "Le paiement du salaire doit être constaté par la délivrance d'un bulletin de paie établi en malagasy et/ou en français par l'employeur ou son représentant. Le bulletin de paie peut être un document en version papier, manuel ou informatisé, émargé par chaque travailleur intéressé ou par deux témoins s'il est illettré. Lorsque la sécurité de la correspondance électronique et la nécessité de la sauvegarde de la sincérité du document sont garanties, le bulletin de paie peut également être un document informatisé en version électronique, qui peut être remis au travailleur par procédé informatique. Dans ce cas, une réponse expresse du travailleur ou l’accusé de réception automatique, lorsqu’il est fiable selon les dispositions de la législation régissant la correspondance et la signature électronique, vaut «accusé de réception » de la part du travailleur. Le paiement du salaire peut également être constaté par un document bancaire ou par un carnet à souche qui est coté et paraphé. La contexture du bulletin de paie est fixée par Arrêté du Ministre chargé du Travail. L'acceptation sans protestation ni réserve par le travailleur d'un bulletin de paie ne peut valoir renonciation de sa part au paiement de tout ou partie du salaire, des indemnités et des accessoires du salaire qui lui sont dus en vertu des dispositions législatives, réglementaires ou contractuelles. Elle ne peut valoir non plus compte arrêté ou réglé.", resume: "Le paiement du salaire est constaté par un bulletin de paie en malagasy et/ou en français (papier ou électronique). L'acceptation sans réserve d'un bulletin ne vaut pas renonciation au paiement des sommes dues ni compte arrêté.", motsCles: ["bulletin de paie","salaire","renonciation","fiche de paie"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 95", equivalent: "bulletin-paie" },
  { id: "l24-96", numero: "96", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Pas de renonciation aux droits", texte: "Toute convention ou transaction passée entre l'employeur et le travailleur ne peut signifier, pour ce dernier, renonciation aux droits qu'il tient de l’exécution du contrat, de la convention collective et des dispositions législatives et réglementaires.", resume: "Aucune convention ou transaction entre l'employeur et le travailleur ne peut signifier pour ce dernier renonciation aux droits qu'il tient du contrat, de la convention collective ou de la loi.", motsCles: ["renonciation","transaction","solde de tout compte","droits"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 96", equivalent: "renonciation" },
  { id: "l24-100", numero: "100", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Retenues sur salaire", texte: "En-dehors des prélèvements obligatoires fixés par la réglementation en vigueur et des avances spéciales accordées par l’employeur au travailleur, il ne peut être fait de retenues sur les appointements ou salaires des travailleurs que par saisie-arrêt ou cession volontaire, conformément aux dispositions du Code de procédure civile. La cession des rémunérations visée à l'alinéa premier du présent article ne peut être consentie, quel qu'en soit le montant, que par déclaration souscrite par le cédant en personne devant le Président du Tribunal de son domicile. Toutefois lorsque le siège de la juridiction est éloigné du domicile du cédant de plus de 20 km, la déclaration peut être reçue par le Chef de l'unité administrative de ce lieu ou à défaut par l’Inspecteur de travail et des lois sociales, si le bureau de ce dernier est plus accessible au travailleur. Pour pouvoir donner lieu à retenue directe sur le salaire, les avances spéciales consenties par l'employeur au travailleur doivent faire l’objet d’un accord écrit signé des deux parties, rédigé au moins en deux exemplaires. Les retenues sur salaire au titre de l’octroi de logement et de vivres sont permises dans les conditions d’un texte règlementaire.", resume: "En dehors des prélèvements obligatoires et des avances spéciales, il ne peut être fait de retenue sur salaire que par saisie-arrêt ou cession volontaire. Les avances doivent faire l'objet d'un accord écrit des deux parties.", motsCles: ["retenue","saisie","avance","acompte","salaire"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 100" },
  { id: "l24-104", numero: "104", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Sommes retenues à tort", texte: "Les sommes retenues au travailleur en contravention des dispositions ci-dessus portent intérêt à son profit au taux légal depuis la date où elles auraient dû être payées, et peuvent être réclamées par lui jusqu'à prescription, le cours en étant suspendu pendant la durée du contrat.", resume: "Les sommes retenues en violation des règles portent intérêt à taux légal au profit du travailleur et peuvent être réclamées jusqu'à prescription, dont le cours est suspendu pendant la durée du contrat.", motsCles: ["retenue","intérêt","prescription"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 104" },
  { id: "l24-105", numero: "105", loi: "2024-014", theme: "Rémunération et paiement du salaire", titre: "Prescription : 12 mois", texte: "Par dérogation au principe posé par la Loi relative à la Théorie Générale des Obligations, l'action en paiement des salaires et accessoires de salaires ainsi que des indemnités de préavis et de licenciement se prescrit par douze (12) mois.", resume: "L'action en paiement des salaires et accessoires ainsi que des indemnités de préavis et de licenciement se prescrit par 12 mois.", motsCles: ["prescription","12 mois","salaire","préavis","licenciement"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 105", equivalent: "prescription-salaire" },
  { id: "l24-108", numero: "108", loi: "2024-014", theme: "Durée du travail, repos et travail de nuit", titre: "Travail effectif", texte: "La durée du travail s’entend du travail effectif. Le temps nécessaire à l’habillage, au déshabillage et à la restauration n’entre pas dans le calcul du temps de travail effectif. Le temps nécessaire à la pause est fixé par des dispositions négociées dans la convention collective ou toute autre forme d’accord collectif ou dans le contrat de travail.", resume: "La durée du travail s'entend du travail effectif. Le temps d'habillage, de déshabillage et de restauration n'y entre pas. Le temps de pause est fixé par accord collectif ou par le contrat.", motsCles: ["travail effectif","pause","habillage","restauration"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 108", equivalent: "temps-effectif" },
  { id: "l24-109", numero: "109", loi: "2024-014", theme: "Durée du travail, repos et travail de nuit", titre: "Durée légale du travail et heures supplémentaires", texte: "Sous réserve des dispositions de l'alinéa 2 du présent article, dans tous les établissements assujettis à la présente loi, même d'enseignement ou de bienfaisance, la durée légale du travail des employés ou ouvriers de l'un ou de l'autre sexe, de tout âge, travaillant à temps, à la tâche ou aux pièces ne peut excéder cent soixante-treize heures trente-trois (173,33H) par mois ou quarante heures (40H) par semaine dans le respect des dispositions légales concernant les heures de repos quotidien et hebdomadaire. Quel que soit le mode de rémunération, les heures effectuées au-delà de la durée hebdomadaire du travail visée à l’alinéa premier du présent article constituent des heures supplémentaires. Dans toutes les entreprises agricoles, les heures de travail sont basées sur deux mille deux cent (2200) heures par an. Dans cette limite et compte tenu des saisons, les modalités d’application de la durée hebdomadaire du travail et les règles régissant les heures supplémentaires sont précisées par voie règlementaire, tel que le stipule l’article 110 ci-dessous.", resume: "La durée légale est de 173,33 heures par mois ou 40 heures par semaine. Les heures effectuées au-delà de la durée hebdomadaire sont des heures supplémentaires, quel que soit le mode de rémunération. Dans l'agriculture, la base est de 2 200 heures par an.", motsCles: ["durée du travail","40 heures","173","33 heures","heures supplémentaires","agricole"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 109", equivalent: "duree-travail" },
  { id: "l24-110", numero: "110", loi: "2024-014", theme: "Durée du travail, repos et travail de nuit", titre: "Heures supplémentaires : règles fixées par décret", texte: "Des Décrets pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi précisent les activités assujetties à une durée de travail de 173, 33 heures par mois et celles assujetties à une durée de travail de 40 heures par semaine et déterminent par branche d'activité et par catégorie professionnelle, s'il y a lieu, les modalités d'application de la durée du travail et des dérogations, la nature et la durée maximum des heures supplémentaires qui peuvent être effectuées avec ou sans autorisation préalable, ainsi que le taux de majoration qui leur est applicable.", resume: "Des décrets fixent par branche et catégorie les modalités de la durée du travail et dérogations, la nature et la durée maximale des heures supplémentaires avec ou sans autorisation préalable, et leur taux de majoration.", motsCles: ["heures supplémentaires","majoration","décret","dérogation"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 110", equivalent: "hs-decret" },
  { id: "l24-112", numero: "112", loi: "2024-014", theme: "Durée du travail, repos et travail de nuit", titre: "Équivalences", texte: "Soit en raison de la nature du travail, soit en raison de son caractère intermittent, le présent Code du travail admet des équivalences, c'est-à-dire, une durée de présence considérée comme correspondant à un travail effectif d'une durée inférieure. L’équivalence joue en matière d'heures supplémentaires. Les catégories d’emploi et les heures d’équivalences y afférentes dans les différentes branches d’activités sont déterminées par un Décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi.", resume: "Le Code admet des équivalences (durée de présence correspondant à un travail effectif plus court) selon la nature ou le caractère intermittent du travail ; elles jouent en matière d'heures supplémentaires et sont fixées par décret.", motsCles: ["équivalence","présence","heures supplémentaires","décret"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 112" },
  { id: "l24-113", numero: "113", loi: "2024-014", theme: "Durée du travail, repos et travail de nuit", titre: "Repos journalier de 12 heures", texte: "Tout travailleur doit jouir d’un repos journalier continu d’au moins douze (12) heures.", resume: "Tout travailleur doit jouir d'un repos journalier continu d'au moins 12 heures.", motsCles: ["repos journalier","12 heures"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 113" },
  { id: "l24-114", numero: "114", loi: "2024-014", theme: "Durée du travail, repos et travail de nuit", titre: "Repos hebdomadaire", texte: "Le repos hebdomadaire est obligatoire. Il est au minimum de vingt-quatre (24) heures consécutives par semaine. Il a lieu en principe le dimanche. Un Décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi détermine les modalités d'application du paragraphe précédent, notamment les professions pour lesquelles le repos hebdomadaire pourra être exceptionnellement et pour des motifs nettement établis, soit plus de vingt-quatre (24) heures, soit donné par roulement ou collectivement d'autres jours que le dimanche, soit suspendu par compensation des fêtes rituelles, soit réparti sur une période plus longue que la semaine.", resume: "Le repos hebdomadaire est obligatoire : au moins 24 heures consécutives par semaine, en principe le dimanche. Un décret précise les professions pouvant avoir un repos plus long, par roulement ou d'autres jours.", motsCles: ["repos hebdomadaire","dimanche","24 heures"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 114", equivalent: "repos-hebdo" },
  { id: "l24-115", numero: "115", loi: "2024-014", theme: "Durée du travail, repos et travail de nuit", titre: "Jours fériés et jours « ponts »", texte: "Les jours fériés et les jours «ponts» sont chômés et payés. La liste annuelle limitative des jours fériés jours et celle des jours « ponts» font l'objet d'un Décret pris en Conseil de Gouvernement en début d'année, après avis du Conseil National du Travail et de l’Emploi.", resume: "Les jours fériés et les jours « ponts » sont chômés et payés. La liste annuelle limitative est fixée par décret en début d'année.", motsCles: ["jours fériés","ponts","chômés","payés"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 115", equivalent: "jours-feries" },
  { id: "l24-116", numero: "116", loi: "2024-014", theme: "Durée du travail, repos et travail de nuit", titre: "Majoration du dimanche et des jours fériés", texte: "Un Décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi fixe les modalités d’application du repos hebdomadaire et le taux de majoration du travail du dimanche et des jours fériés.", resume: "Un décret fixe les modalités du repos hebdomadaire et le taux de majoration du travail du dimanche et des jours fériés.", motsCles: ["majoration","dimanche","férié","décret"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 116" },
  { id: "l24-118", numero: "118", loi: "2024-014", theme: "Durée du travail, repos et travail de nuit", titre: "Travail de nuit : définition", texte: "Le travail effectué entre vingt-deux (22) heures et cinq (05) heures du matin est considéré comme travail de nuit.", resume: "Le travail effectué entre 22 heures et 5 heures du matin est du travail de nuit.", motsCles: ["nuit","22 heures","5 heures"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 118" },
  { id: "l24-121", numero: "121", loi: "2024-014", theme: "Durée du travail, repos et travail de nuit", titre: "Inaptitude au travail de nuit", texte: "Les travailleurs qui, pour des raisons de santé, sont certifiés inaptes au travail de nuit par le service médical du travail ou, à défaut, par un Médecin agréé ne peuvent être licenciés que lorsque que leur transfert à un poste similaire de jour n’est pas réalisable.", resume: "Les travailleurs certifiés inaptes au travail de nuit pour raisons de santé ne peuvent être licenciés que si leur transfert à un poste similaire de jour n'est pas réalisable.", motsCles: ["nuit","inaptitude","licenciement","transfert"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 121" },
  { id: "l24-122", numero: "122", loi: "2024-014", theme: "Durée du travail, repos et travail de nuit", titre: "Inaptitude temporaire au travail de nuit", texte: "Chaque fois que cela est réalisable, un travailleur de nuit qui, pour des raisons de santé, est certifié temporairement inapte au travail de nuit par le service médical du travail ou, à défaut, par un Médecin agréé est affecté, pour la durée de son inaptitude, à un poste similaire de jour. Lorsque le transfert à un tel poste n'est pas réalisable, l’employeur peut mettre en œuvre la suspension du contrat pour maladie prévue au paragraphe 3 de l’article 31 de la présente loi. Si la maladie du travailleur dépasse six mois, l’employeur ne peut le licencier que s’il n’existe pas encore de poste similaire de jour vacant, où il peut l’affecter prioritairement.", resume: "Un travailleur de nuit temporairement inapte est affecté, quand c'est réalisable, à un poste de jour similaire ; sinon le contrat peut être suspendu pour maladie. Si la maladie dépasse 6 mois, il ne peut être licencié que s'il n'existe pas de poste de jour similaire vacant.", motsCles: ["nuit","inaptitude","maladie","poste de jour"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 122" },
  { id: "l24-123", numero: "123", loi: "2024-014", theme: "Durée du travail, repos et travail de nuit", titre: "Majoration du travail de nuit", texte: "Les heures de travail de nuit donnent lieu à une majoration de salaire dont les taux sont déterminés par Décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi.", resume: "Les heures de nuit donnent lieu à une majoration de salaire dont les taux sont fixés par décret.", motsCles: ["nuit","majoration","décret"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 123", equivalent: "travail-nuit" },
  { id: "l24-125", numero: "125", loi: "2024-014", theme: "Congés payés et paternité", titre: "Congé payé : acquisition", texte: "Sauf dispositions plus favorables des conventions collectives ou du contrat individuel de travail, le travailleur acquiert droit au congé payé à la charge de l'employeur, à raison de deux jours et demi (02,5 jours) calendaires par mois de service effectif.", resume: "Sauf dispositions plus favorables, le travailleur acquiert 2,5 jours calendaires de congé payé par mois de service effectif, à la charge de l'employeur.", motsCles: ["congés payés","2","5 jours","acquisition"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 125", equivalent: "conges-payes" },
  { id: "l24-126", numero: "126", loi: "2024-014", theme: "Congés payés et paternité", titre: "Absences assimilées à du service effectif", texte: "Sont assimilées à un (01) mois de service effectif les périodes équivalentes à quatre (04) semaines ou à vingt-quatre (24) jours de travail. Sont également assimilées à un service effectif : 1. les absences régulières pour maladie certifiées par le service médical du travail ou, à défaut, par un Médecin agréé, dans la limite de six (06) mois ; 2. les absences régulières pour accident de travail et maladies professionnelles ; 3. les périodes de repos de la femme en couche telles que prévues à l'article 142 du présent Code; 4. les permissions exceptionnelles, non déductibles du congé annuel payé, accordées au travailleur à l'occasion d’événements de famille, dans la limite de dix (10) jours par an, sauf dispositions plus favorables des conventions collectives ; 5. les périodes de congé payé ; 6. le congé de paternité prévu à l’article 134 ci-dessous ; 7. les permissions prévues aux dispositions relatives au congé-éducation du présent Code; 8. les absences du travailleur, en cas d'hospitalisation d'un enfant au sens du Code de la prévoyance sociale, dans la limite de deux (02) mois ; 9. les absences régulières en cas d’hospitalisation du conjoint du travailleur dans la limite de quinze (15) jours ; 10. les absences régulières pour participation du travailleur à une compétition sportive nationale ou internationale, dûment attestée par le Ministère en charge du Sport ou les fédérations sportives.", resume: "Sont assimilés à du service effectif pour les congés, notamment : maladie certifiée (6 mois au plus), accident du travail et maladie professionnelle, repos de maternité, congé de paternité, permissions familiales (10 jours par an), congés payés, hospitalisation d'un enfant ou du conjoint dans certaines limites.", motsCles: ["congés","assimilé","maladie","maternité","paternité"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 126", equivalent: "conges-assimiles" },
  { id: "l24-127", numero: "127", loi: "2024-014", theme: "Congés payés et paternité", titre: "Jours fériés et absences non décomptés du congé", texte: "Les jours fériés ainsi que les périodes d’absences régulières ou de suspension légale du contrat de travail pour maladie ou accident ne peuvent pas être comptés dans le congé payé.", resume: "Les jours fériés, ainsi que les périodes d'absence régulière ou de suspension légale du contrat pour maladie ou accident, ne peuvent pas être comptés dans le congé payé.", motsCles: ["congés","jours fériés","maladie"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 127" },
  { id: "l24-128", numero: "128", loi: "2024-014", theme: "Congés payés et paternité", titre: "Planification des congés", texte: "Dans le cadre de son pouvoir général d’organisation et afin d’éviter le cumul de reliquats, l’employeur doit planifier en début d'année le départ en congé payé, en consultation avec les délégués du personnel ou, à défaut, les travailleurs concernés.", resume: "L'employeur doit planifier en début d'année le départ en congé payé, en consultation avec les délégués du personnel ou, à défaut, les travailleurs concernés.", motsCles: ["congés","planification","délégués"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 128" },
  { id: "l24-129", numero: "129", loi: "2024-014", theme: "Congés payés et paternité", titre: "Prescription du droit au congé", texte: "Le droit au congé payé se prescrit par trois (03) ans. Toutefois, cette prescription peut être combattue par la preuve contraire, si le travailleur établit que des défaillances de l’employeur quant à la planification en début d’année ou d’autres motifs de service invoqués par l’employeur ont eu pour effet de l’empêcher de jouir de son droit au congé.", resume: "Le droit au congé payé se prescrit par 3 ans, mais le travailleur peut prouver que l'employeur l'a empêché d'en jouir (défaut de planification, motifs de service).", motsCles: ["congés","prescription","3 ans"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 129" },
  { id: "l24-130", numero: "130", loi: "2024-014", theme: "Congés payés et paternité", titre: "Jouissance et fractionnement du congé", texte: "La jouissance du congé payé est acquise après douze (12) mois de service effectif. La première fraction de quinze (15) jours est obligatoirement prise de manière ininterrompue, dans les trois (03) mois qui suivent l’ouverture du droit au congé, dans la limite de la nécessité de service entendue entre les deux parties. La deuxième fraction peut être, selon l’accord des parties prenant en compte les besoins du travailleur en accord avec les nécessités du service, soit prise de manière fractionnée ou non avant la fin de l'année en cours, soit cumulée sur trois (03) ans. Si les parties en conviennent, les droits au congé des trois (03) dernières années précédant le départ à la retraite peuvent être cumulés et exercés avant la date de départ. La date de début et de fin du congé doit être déterminée à l’avance par les parties. Le congé commence le jour où le travailleur aurait dû travailler s’il n’était pas en congé et se termine la veille de sa reprise de service. Dans les établissements où la fermeture périodique pour congé n’est pas fixée, l’époque à laquelle le congé est pris est déterminée par l’employeur, dans le cadre de la planification visée à l’article 128 ci-dessus, après consultation des délégués du personnel ou, à défaut, des travailleurs intéressés.", resume: "Le congé est acquis après 12 mois de service effectif. Une première fraction de 15 jours est prise sans interruption dans les 3 mois suivant l'ouverture du droit ; la seconde peut être fractionnée avant la fin de l'année ou cumulée sur 3 ans. Les dates sont fixées à l'avance par les parties ; à défaut de fermeture périodique, l'employeur les détermine après consultation.", motsCles: ["congés","12 mois","15 jours","fractionnement","dates"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 130", equivalent: "conges-prise" },
  { id: "l24-131", numero: "131", loi: "2024-014", theme: "Congés payés et paternité", titre: "Allocation de congé payé", texte: "L'employeur doit verser au travailleur, pendant toute la durée du congé, une allocation qui est au moins égale au douzième (1/12) des salaires et des divers éléments de la rémunération définis par la présente loi, dont le travailleur bénéficiait au cours des douze (12) mois ayant précédé la date de congé, à l'exception des remboursements de frais. Les divers éléments de la rémunération visés à l’alinéa premier du présent article comprennent, lorsque cette rémunération comporte des prestations en nature, la contre-valeur en espèces de celles-ci, à moins qu'il ne s'agisse de prestations permanentes dont l'intéressé jouit indépendamment du congé payé. Cette allocation doit être versée au travailleur avant son départ en congé, à moins qu'il n’en soit convenu autrement et par écrit entre l'employeur et le travailleur.", resume: "Pendant le congé, l'employeur verse une allocation au moins égale au douzième des rémunérations des 12 derniers mois (hors remboursement de frais), versée avant le départ sauf accord écrit contraire.", motsCles: ["congés","allocation","1/12","indemnité"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 131", equivalent: "conges-allocation" },
  { id: "l24-132", numero: "132", loi: "2024-014", theme: "Congés payés et paternité", titre: "Pas de renonciation au congé", texte: "Est nul et non avenu tout accord écrit ou verbal portant renonciation de la part du travailleur au droit au congé. Tant que le contrat de travail reste en vigueur, est nul et non avenu tout accord prévoyant l’octroi d’une indemnité quelconque en lieu et place du congé.", resume: "Tout accord renonçant au droit au congé est nul. Tant que le contrat est en vigueur, un accord prévoyant une indemnité à la place du congé est nul.", motsCles: ["congés","renonciation","nullité","indemnité"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 132" },
  { id: "l24-133", numero: "133", loi: "2024-014", theme: "Congés payés et paternité", titre: "Congés non pris à la fin du contrat", texte: "En cas de rupture ou d'expiration du contrat avant que le travailleur ait exercé ses droits au congé, une indemnité compensatoire calculée sur la base des droits acquis doit être accordée en lieu et place du congé.", resume: "En cas de rupture ou d'expiration du contrat avant l'exercice du droit au congé, une indemnité compensatrice calculée sur les droits acquis est due en lieu et place du congé.", motsCles: ["congés","indemnité compensatrice","fin de contrat"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 133", equivalent: "conges-rupture" },
  { id: "l24-134", numero: "134", loi: "2024-014", theme: "Congés payés et paternité", titre: "Congé de paternité", texte: "Sauf accord plus favorable des parties, le travailleur salarié conjoint légitime d’une femme qui accouche a droit à trois (3) jours de congé de paternité, payés par l’employeur comme des jours de travail effectif.", resume: "Sauf accord plus favorable, le salarié conjoint légitime d'une femme qui accouche a droit à 3 jours de congé de paternité payés comme des jours de travail effectif.", motsCles: ["paternité","naissance","3 jours","père"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 134" },
  { id: "l24-137", numero: "137", loi: "2024-014", theme: "Maternité", titre: "Travaux interdits aux femmes enceintes", texte: "Un Décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi fixe la nature des travaux interdits aux femmes enceintes et à celles qui allaitent.", resume: "Un décret fixe la nature des travaux interdits aux femmes enceintes et à celles qui allaitent.", motsCles: ["enceinte","travaux interdits","décret"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 137" },
  { id: "l24-138", numero: "138", loi: "2024-014", theme: "Maternité", titre: "Candidate à l'emploi et grossesse", texte: "Une femme candidate à l’emploi n’est pas tenue de déclarer son état de grossesse, sauf pour les travaux interdits aux femmes enceintes visés aux articles 137, 139 et 146 du présent Code, ainsi que pour les travaux qui comportent un risque reconnu ou significatif pour la santé de la femme et de l'enfant.", resume: "Une candidate à l'emploi n'est pas tenue de déclarer sa grossesse, sauf pour les travaux interdits aux femmes enceintes ou comportant un risque reconnu ou significatif pour la mère et l'enfant.", motsCles: ["grossesse","embauche","déclaration"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 138" },
  { id: "l24-139", numero: "139", loi: "2024-014", theme: "Maternité", titre: "Examen et affectation de la femme enceinte", texte: "La femme enceinte dont l’état de grossesse est reconnu ainsi que la femme qui allaite peuvent se faire examiner par le Médecin du service médical du travail ou, à défaut, par un Médecin agréé, pour déterminer si les travaux dont elles sont chargés ne présentent pas de risque pour elles ou pour l’enfant. L'Inspecteur du travail et des lois sociales du ressort peut également requérir l'examen visé au premier alinéa du présent article. La femme enceinte ne peut être maintenue dans un emploi ainsi reconnu comme présentant des risques et doit être affectée à un emploi adapté à son état de grossesse. Pendant la période de mutation, le salaire et les éléments de salaire à caractère fixe sont conservés.", resume: "La femme enceinte ou allaitante peut se faire examiner par le médecin du travail pour vérifier que son travail ne présente pas de risque. Si l'emploi est à risque, elle est affectée à un emploi adapté en conservant son salaire fixe.", motsCles: ["grossesse","médecin du travail","mutation","salaire"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 139" },
  { id: "l24-140", numero: "140", loi: "2024-014", theme: "Maternité", titre: "Interdiction de licencier une femme enceinte", texte: "Aucun employeur ne peut résilier le contrat de travail d'une femme salariée lorsqu'elle est en état de grossesse constatée médicalement. Toutefois, le contrat peut être résilié pour des motifs légitimes, des causes réelles et sérieuses, non liés à l’état de grossesse. Les dispositions des précédents alinéas ne font pas obstacle à l'échéance du contrat de travail à durée déterminée.", resume: "Aucun employeur ne peut résilier le contrat d'une salariée dont la grossesse est constatée médicalement, sauf motifs légitimes, causes réelles et sérieuses non liés à la grossesse. Cela ne fait pas obstacle à l'échéance d'un CDD.", motsCles: ["grossesse","licenciement","interdit","CDD"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 140", equivalent: "grossesse-licenciement" },
  { id: "l24-141", numero: "141", loi: "2024-014", theme: "Maternité", titre: "Grossesse et période d'essai", texte: "L’état de grossesse ne doit pas être pris en considération pour résilier un contrat de travail au cours de la période d’essai.", resume: "L'état de grossesse ne doit pas être pris en considération pour résilier un contrat pendant la période d'essai.", motsCles: ["grossesse","essai","rupture"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 141", equivalent: "grossesse-essai" },
  { id: "l24-142", numero: "142", loi: "2024-014", theme: "Maternité", titre: "Démission de la femme enceinte", texte: "Toute femme enceinte dont l’état est constaté par le service médical du travail ou, à défaut, par un médecin agréé peut rompre son contrat sans préavis et sans avoir de ce fait à payer une indemnité de rupture de contrat.", resume: "La femme enceinte dont l'état est constaté peut rompre son contrat sans préavis et sans payer d'indemnité de rupture.", motsCles: ["grossesse","démission","sans préavis"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 142" },
  { id: "l24-143", numero: "143", loi: "2024-014", theme: "Maternité", titre: "Congé de maternité", texte: "A l'occasion de son accouchement et sans que cette interruption de service puisse être considérée comme une cause de rupture de contrat, toute femme a le droit de suspendre son travail pendant quatorze (14) semaines consécutives dont huit (08) semaines postérieures à la délivrance. Cette suspension peut être prolongée de quatre (04) semaines au maximum dans les cas dûment constatés par le service médical du travail ou, à défaut, par un Médecin agréé, de maladie de la mère résultant de la grossesse ou des couches ou de pathologie du nouveau-né. Cette période ne peut être confondue avec le congé annuel. Elle a le droit, pendant cette période, à la charge de la Caisse Nationale de Prévoyance Sociale, au remboursement des frais d'accouchement et le cas échéant, des soins médicaux, dans la limite des tarifs des formations sanitaires. Pendant la durée du congé de maternité, le travailleur conserve le droit aux prestations en nature et perçoit la totalité de son salaire. La moitié (1/2) du salaire est à la charge de la Caisse Nationale de Prévoyance Sociale, l’autre moitié (1/2) étant payée par l’employeur. L’intégralité de la rémunération visée au cinquième alinéa du présent article correspondant au minimum de quatorze (14) semaines est versée, même si l’accouchement ne coïncide pas à la date probable d’accouchement ou si l’enfant est mort-né. A défaut d'affiliation à la Caisse Nationale de Prévoyance Sociale, le remboursement des frais d'accouchement et de soins médicaux et le paiement de la totalité du salaire sont à la charge de l'employeur.", resume: "À l'accouchement, la femme peut suspendre son travail pendant 14 semaines consécutives dont 8 après la délivrance, prolongeables de 4 semaines maximum sur constat médical. Elle perçoit la totalité de son salaire : moitié à la charge de la CNaPS, moitié à la charge de l'employeur (ou tout à la charge de l'employeur si non affiliation).", motsCles: ["maternité","14 semaines","accouchement","CNaPS","salaire"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 143", equivalent: "maternite" },
  { id: "l24-144", numero: "144", loi: "2024-014", theme: "Maternité", titre: "Repos d'allaitement", texte: "Pendant une période de quinze (15) mois à compter de la naissance de l'enfant, la mère a droit à des repos pour allaitement. La durée totale de ces repos, qui sont payés comme temps de travail, ne peut dépasser une heure (01) par journée de travail. Ce droit aux repos pour allaitement est calculé au prorata du temps de travail par jour pour les travailleurs à temps partiel. La mère peut, pendant cette période, rompre son contrat sans préavis et sans avoir de ce fait à payer une indemnité de rupture.", resume: "Pendant 15 mois après la naissance, la mère a droit à des repos d'allaitement payés comme temps de travail, d'une heure par jour au plus. Elle peut aussi rompre son contrat sans préavis ni indemnité de rupture.", motsCles: ["allaitement","15 mois","1 heure","repos"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 144", equivalent: "allaitement" },
  { id: "l24-146", numero: "146", loi: "2024-014", theme: "Maternité", titre: "Travail de nuit des femmes enceintes", texte: "Les femmes enceintes et celles qui allaitent ne doivent pas être employées la nuit : 1. avant et après la naissance d'un enfant, pendant une période d'au moins seize (16) semaines, dont au moins huit (08) avant la date présumée de l'accouchement ; 2. sur présentation d'un certificat médical qui atteste la nécessité de cette interdiction pour la santé de la mère ou de l'enfant, pendant d'autres périodes se situant: - au cours de la grossesse; - durant la période d’allaitement visée à l’article 143 ci-dessus.", resume: "Les femmes enceintes ou qui allaitent ne doivent pas être employées la nuit pendant au moins 16 semaines autour de la naissance (dont au moins 8 avant), ni pendant d'autres périodes sur certificat médical.", motsCles: ["enceinte","nuit","interdiction","certificat"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 146" },
  { id: "l24-147", numero: "147", loi: "2024-014", theme: "Travail des enfants et handicap", titre: "Âge minimum d'accès à l'emploi", texte: "L’âge minimum légal d’accès à l’emploi est de quinze (15) ans sur toute l’étendue du territoire de Madagascar. Cet âge minimum d’accès à l’emploi ne doit pas être inférieur à l’âge auquel cesse la scolarité obligatoire. L’autorisation expresse d’un des parents ou du tuteur est obligatoire pour l’emploi d’un enfant mineur.", resume: "L'âge minimum d'accès à l'emploi est de 15 ans et ne peut être inférieur à l'âge de fin de scolarité obligatoire. L'autorisation expresse d'un parent ou du tuteur est obligatoire pour l'emploi d'un mineur.", motsCles: ["âge minimum","15 ans","mineur","autorisation"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 147", equivalent: "age-minimum" },
  { id: "l24-148", numero: "148", loi: "2024-014", theme: "Travail des enfants et handicap", titre: "Travaux interdits aux enfants", texte: "Des décrets pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi fixent la nature des travaux interdits aux enfants.", resume: "Des décrets fixent la nature des travaux interdits aux enfants.", motsCles: ["enfants","travaux interdits","décret"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 148" },
  { id: "l24-149", numero: "149", loi: "2024-014", theme: "Travail des enfants et handicap", titre: "Mineurs de moins de 18 ans : durée du travail", texte: "Dans les établissements assujettis à la présente loi, les enfants mineurs et les apprentis âgés de moins de dix-huit (18) ans de l'un ou de l'autre sexe ne peuvent être employés à un travail effectif de plus de huit (08) heures par jour et de quarante (40) heures par semaine. Le travail de nuit ainsi que les heures supplémentaires sont interdits aux enfants jusqu’à l’âge de dix-huit (18) ans. Un repos quotidien de douze (12) heures consécutives est obligatoire pour les enfants travailleurs.", resume: "Avant 18 ans : au plus 8 heures par jour et 40 heures par semaine ; travail de nuit et heures supplémentaires interdits ; repos quotidien de 12 heures consécutives.", motsCles: ["mineur","18 ans","8 heures","nuit","heures supplémentaires"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 149", equivalent: "mineurs-duree" },
  { id: "l24-150", numero: "150", loi: "2024-014", theme: "Travail des enfants et handicap", titre: "Enfants de moins de 15 ans", texte: "Les enfants ne peuvent être employés dans aucune entreprise, même comme apprentis, avant l'âge de quinze (15) ans, sans l'autorisation de l'Inspecteur du travail et des lois sociales dont la décision tient compte des circonstances locales, des tâches qui peuvent leur être demandées et à la condition que les travaux ne soient pas nuisibles à leur santé et à leur développement normal.", resume: "Avant 15 ans, un enfant ne peut être employé, même comme apprenti, sans l'autorisation de l'inspecteur du travail, à la condition que les travaux ne nuisent pas à sa santé ni à son développement.", motsCles: ["enfant","15 ans","autorisation","inspecteur","apprenti"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 150", equivalent: "enfants-autorisation" },
  { id: "l24-151", numero: "151", loi: "2024-014", theme: "Travail des enfants et handicap", titre: "Examen médical des enfants et adolescents", texte: "L'Inspecteur du travail et des lois sociales peut requérir l'examen des enfants par un Médecin agréé, en vue de vérifier si le travail dont ils sont chargés n'excède pas leurs forces. Cette réquisition est de droit à la demande de l'intéressé. L'enfant ne peut être maintenu dans un emploi ainsi reconnu au-dessus de ses forces et doit être affecté à un emploi non nuisible à sa santé ou à son développement. Le cas échéant, le contrat peut être résilié avec paiement de l'indemnité de préavis. Dans tous les cas, les enfants et les adolescents ne pourront être admis à un emploi qu'à la suite d'un examen médical.", resume: "L'inspecteur peut requérir l'examen de l'enfant par un médecin agréé ; l'enfant ne peut être maintenu dans un emploi au-dessus de ses forces. Enfants et adolescents ne sont admis à un emploi qu'après examen médical.", motsCles: ["enfant","examen médical","inspecteur"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 151" },
  { id: "l24-153", numero: "153", loi: "2024-014", theme: "Travail des enfants et handicap", titre: "Non-discrimination des personnes en situation de handicap", texte: "Aucune discrimination ne peut être faite en matière de travail ou d'emploi à égalité de capacité et d'aptitude entre les personnes valides et les personnes en situation de handicap, du fait de leur handicap. Les personnes en situation de handicap ont droit au travail et à l'emploi, à l'égalité de chances et de traitement en matière d'apprentissage, de formation professionnelle et d'emploi.", resume: "À égalité de capacité et d'aptitude, aucune discrimination ne peut être faite en raison du handicap. Les personnes en situation de handicap ont droit au travail et à l'égalité de chances et de traitement.", motsCles: ["handicap","discrimination","égalité"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 153", equivalent: "handicap-discrimination" },
  { id: "l24-163", numero: "163", loi: "2024-014", theme: "Sécurité et santé au travail", titre: "Obligation générale de sécurité", texte: "L'employeur doit assurer la sécurité et la santé des travailleurs dans tous les aspects liés au travail.", resume: "L'employeur doit assurer la sécurité et la santé des travailleurs dans tous les aspects liés au travail.", motsCles: ["sécurité","santé","employeur","obligation"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 163" },
  { id: "l24-164", numero: "164", loi: "2024-014", theme: "Sécurité et santé au travail", titre: "Évaluation des risques (DUER) et plan de prévention (PAP)", texte: "L’employeur a l’obligation de promouvoir une culture de prévention pour s’assurer que les lieux de travail, les machines, les matériels et les procédés de travail placés sous leur contrôle ne présentent pas de risques pour la sécurité et la santé des travailleurs. L’employeur a l’obligation : 1. d’évaluer périodiquement, ou de faire évaluer par toutes autres personnes compétentes, les risques pour la sécurité et la santé des travailleurs qu’il emploie et à cet effet, d’établir et de mettre à jour un Document Unique d’Evaluation des Risques, en abrégé DUER, pour la sécurité et la santé des travailleurs ; 2. d’élaborer et de mettre en œuvre annuellement un Plan d’Action de Prévention, en abrégé PAP, pour garantir la sécurité et la santé des travailleurs. Un Décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi détermine les modalités d’évaluation des risques, d’établissement des DUER et d’élaboration et de mise en œuvre du PAP.", resume: "L'employeur évalue périodiquement les risques, établit et met à jour un Document Unique d'Évaluation des Risques (DUER) et élabore chaque année un Plan d'Action de Prévention (PAP). Un décret en précise les modalités.", motsCles: ["DUER","PAP","évaluation des risques","prévention"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 164" },
  { id: "l24-165", numero: "165", loi: "2024-014", theme: "Sécurité et santé au travail", titre: "Équipements de protection", texte: "L’employeur doit fournir gratuitement en cas de besoin les équipements de protection collectifs et individuels appropriés afin de prévenir les accidents ou autres effets préjudiciables à la santé. Il doit également maintenir ces équipements en bon état de fonctionnement et effectuer les réparations et changements nécessaires et s’assurer que les travailleurs les utilisent correctement.", resume: "L'employeur doit fournir gratuitement, en cas de besoin, les équipements de protection collectifs et individuels appropriés, les maintenir en bon état et s'assurer que les travailleurs les utilisent correctement.", motsCles: ["équipement de protection","gratuit","sécurité"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 165", equivalent: "securite-equipements" },
  { id: "l24-167", numero: "167", loi: "2024-014", theme: "Sécurité et santé au travail", titre: "Urgences, accidents et premiers secours", texte: "L’employeur avec le concours des médecins du travail est tenu de prévoir des mesures permettant de faire face aux situations d’urgence et aux accidents et de fournir des moyens suffisants pour l’administration des premiers secours.", resume: "Avec le concours des médecins du travail, l'employeur doit prévoir des mesures face aux situations d'urgence et aux accidents et fournir des moyens suffisants pour les premiers secours.", motsCles: ["premiers secours","urgence","accident"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 167" },
  { id: "l24-168", numero: "168", loi: "2024-014", theme: "Sécurité et santé au travail", titre: "Information sur les risques", texte: "L’employeur est tenu d’informer les travailleurs ou leurs représentants sur les risques pour leur sécurité et leur santé ainsi que les mesures de prévention prises pour garantir un lieu de travail sûr et sain.", resume: "L'employeur informe les travailleurs ou leurs représentants des risques pour leur sécurité et leur santé et des mesures de prévention prises.", motsCles: ["information","risques","prévention"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 168" },
  { id: "l24-169", numero: "169", loi: "2024-014", theme: "Sécurité et santé au travail", titre: "Formation à la sécurité", texte: "L’employeur a l’obligation de veiller à ce que chaque travailleur reçoive une formation appropriée gratuite en matière de sécurité et de santé au travail. Des formations spécifiques devront être définies et réalisées au bénéfice des travailleurs et de leurs représentants ayant les missions de promouvoir la sécurité et la santé au travail.", resume: "L'employeur veille à ce que chaque travailleur reçoive une formation appropriée gratuite en matière de sécurité et de santé au travail.", motsCles: ["formation","sécurité","gratuite"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 169", equivalent: "securite-formation" },
  { id: "l24-171", numero: "171", loi: "2024-014", theme: "Sécurité et santé au travail", titre: "Comité Sécurité et Santé au Travail (CSST)", texte: "Au niveau de l’entreprise utilisant à partir de cinquante (50) travailleurs, un Comité Sécurité et Santé au Travail, en abrégé CSST, doit être mis en place pour permettre la participation des travailleurs visée à l’article 177 ci-dessus. Le CSST est rattaché au Comité d’entreprise. Jusqu’à la mise en place du Comité d’entreprise, il est provisoirement constitué en structure autonome. Les détails des missions du CSST ainsi que son organisation et son fonctionnement sont précisés par décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi.", resume: "À partir de 50 travailleurs, un Comité Sécurité et Santé au Travail doit être mis en place, rattaché au comité d'entreprise ; un décret en précise les missions et le fonctionnement.", motsCles: ["CSST","comité","50 travailleurs","sécurité"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 171" },
  { id: "l24-173", numero: "173", loi: "2024-014", theme: "Sécurité et santé au travail", titre: "Droit d'alerte et de retrait", texte: "Le travailleur en cas de danger menaçant sa santé et/ou sa sécurité peut exercer le droit d’alerte et de retrait temporaire du poste de travail, jusqu'à ce que l'employeur ait pris des mesures pour y remédier. À cet effet, l’employeur ne pourra pas demander aux travailleurs de reprendre le travail dans une situation où persiste un péril imminent et grave pour la vie ou la santé. Un Décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi détermine les modalités du droit de retrait.", resume: "En cas de danger menaçant sa santé ou sa sécurité, le travailleur peut exercer son droit d'alerte et de retrait du poste jusqu'à ce que l'employeur ait pris des mesures. L'employeur ne peut demander de reprendre le travail tant qu'un péril imminent et grave persiste.", motsCles: ["droit de retrait","danger","alerte","sécurité"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 173" },
  { id: "l24-174", numero: "174", loi: "2024-014", theme: "Sécurité et santé au travail", titre: "Gratuité des mesures de sécurité", texte: "Les mesures de sécurité et de santé au travail ne doivent entraîner aucune dépense pour les travailleurs.", resume: "Les mesures de sécurité et de santé au travail ne doivent entraîner aucune dépense pour les travailleurs.", motsCles: ["sécurité","gratuité","dépense"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 174" },
  { id: "l24-181", numero: "181", loi: "2024-014", theme: "Sécurité et santé au travail", titre: "Service médical du travail", texte: "Le service médical du travail est un service investi de fonctions essentiellement préventives. Il a pour mission de prévenir toute altération de la santé des travailleurs du fait de leur travail, en particulier de surveiller les conditions de sécurité et de santé sur les lieux de travail. L’affiliation du travailleur au service médical du travail doit se faire dans les quinze (15) jours qui suivent la prise de service.", resume: "Le service médical du travail a des fonctions essentiellement préventives. L'affiliation du travailleur doit se faire dans les 15 jours qui suivent la prise de service.", motsCles: ["médecin du travail","service médical","affiliation","15 jours"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 181" },
  { id: "l24-200", numero: "200", loi: "2024-014", theme: "Syndicats et représentants du personnel", titre: "Protection contre la discrimination syndicale", texte: "Les travailleurs sont protégés contre tous actes de discrimination portant atteinte à la liberté syndicale en matière d'emploi. Il est interdit de : 1. subordonner l'emploi d'un travailleur à son affiliation ou à la cessation de ses activités au sein d’un syndicat ; 2. congédier un travailleur ou lui porter préjudice par tous autres moyens, en raison de son affiliation syndicale ou de sa participation à des activités syndicales.", resume: "Il est interdit de subordonner l'emploi à l'affiliation ou à la non-affiliation syndicale, et de congédier un travailleur ou de lui porter préjudice en raison de son affiliation ou de ses activités syndicales.", motsCles: ["syndicat","discrimination","licenciement","liberté syndicale"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 200", equivalent: "syndical-discrimination" },
  { id: "l24-203", numero: "203", loi: "2024-014", theme: "Syndicats et représentants du personnel", titre: "Nullité des mesures contre la liberté syndicale", texte: "Toute mesure prise par l'employeur en violation des dispositions des articles 195 à 202 ci-dessus est considérée comme nulle de plein droit et donne lieu à des dommages intérêts au bénéfice de la personne lésée.", resume: "Toute mesure de l'employeur en violation des articles 195 à 202 est nulle de plein droit et donne lieu à des dommages-intérêts pour la personne lésée.", motsCles: ["syndicat","nullité","dommages-intérêts"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 203" },
  { id: "l24-213", numero: "213", loi: "2024-014", theme: "Syndicats et représentants du personnel", titre: "Délégués syndicaux", texte: "Pour l'accomplissement de leur mission, les délégués syndicaux et intersyndicaux bénéficient: 1. d'un crédit d'heures de huit (08) heures par mois dont l'utilisation se fait en accord avec l'employeur, ce dernier devant être prévenu de l’utilisation du crédit d’heures au moins deux (2) jours ouvrables à l’avance ; 2. de la même protection en matière de licenciement que celle prévue pour les délégués du personnel par l’article 221 ci-dessous. La protection visée au point (2) du présent article s’applique également au responsable syndical dans l’entreprise désigné conformément aux dispositions des statuts et du règlement de leur organisation ainsi qu’à celles du présent Chapitre et des textes règlementaires pris en son application. Les fonctions de délégué syndical sont incompatibles avec celles de délégué du personnel.", resume: "Les délégués syndicaux ont un crédit de 8 heures par mois (avec 2 jours ouvrables de prévenance) et la même protection contre le licenciement que les délégués du personnel.", motsCles: ["délégué syndical","crédit d'heures","8 heures","protection"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 213" },
  { id: "l24-215", numero: "215", loi: "2024-014", theme: "Syndicats et représentants du personnel", titre: "Élection des délégués du personnel", texte: "Les délégués du personnel sont obligatoirement élus dans les établissements où sont employés plus de onze (11) salariés. Tout travailleur de l’établissement peut saisir l’Inspecteur du travail et des lois sociales pour enjoindre à l’employeur d’organiser l’élection des délégués du personnel.", resume: "Des délégués du personnel sont obligatoirement élus dans les établissements employant plus de 11 salariés. Tout travailleur peut saisir l'inspecteur du travail pour enjoindre à l'employeur d'organiser l'élection.", motsCles: ["délégué du personnel","élection","11 salariés","inspecteur"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 215", equivalent: "delegues-election" },
  { id: "l24-221", numero: "221", loi: "2024-014", theme: "Syndicats et représentants du personnel", titre: "Licenciement d'un délégué du personnel", texte: "Tout licenciement d'un délégué du personnel envisagé par l'employeur doit être soumis à la décision de l’Inspecteur du travail et des lois sociales du ressort. La décision motivée de l’Inspecteur du travail et des lois sociales doit être rendue dans un délai de soixante (60) jours ouvrables de la saisine. La même procédure est applicable au licenciement des anciens délégués du personnel pendant une durée de six (06) mois à partir de l'expiration de leur mandat, ainsi qu’au licenciement des candidats aux fonctions des délégués du personnel, dès le dépôt des candidatures et pendant une durée de trois (03) mois après le scrutin. Toutefois, en cas de faute lourde, l'employeur peut prononcer la suspension à titre conservatoire de l'intéressé, après en avoir informé par écrit l'Inspecteur du travail et des lois sociales du ressort. Faute pour l’employeur d’avoir procédé à cette information préalable, la mesure de suspension est réputée être une sanction disciplinaire. Si le licenciement est refusé, la suspension est nulle et non avenue et le délégué du personnel est immédiatement réintégré et ce, nonobstant tout recours que l’employeur pourrait intenter. Si le refus de licenciement est confirmé en dernier ressort par la juridiction compétente et/ou si aucun recours n’a été intenté dans les délais prescrits contre la décision de refus, le travailleur intéressé peut prétendre à des dommages et intérêts fixés par la juridiction compétente. L’employeur a également l’obligation de réintégrer dans ses fonctions, dans les conditions prévues à l’alinéa 5 du présent article, le délégué du personnel qui a eu gain de cause à l’issue d’un recours et ce, malgré un licenciement qui serait déjà intervenu à la suite des décisions prises aux instances inférieures.", resume: "Tout licenciement d'un délégué du personnel doit être soumis à la décision de l'inspecteur du travail, rendue sous 60 jours ouvrables. La règle vaut aussi pour les anciens délégués pendant 6 mois et pour les candidats (dès la candidature et 3 mois après le scrutin). Si le licenciement est refusé, le délégué est réintégré.", motsCles: ["délégué du personnel","licenciement","inspecteur","protection","candidat"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 221", equivalent: "delegue-licenciement" },
  { id: "l24-224", numero: "224", loi: "2024-014", theme: "Syndicats et représentants du personnel", titre: "Crédit d'heures des délégués du personnel", texte: "Chaque délégué du personnel titulaire dispose d’un crédit mensuel de quinze (15) heures pour l’accomplissement de ses fonctions. Cette durée qui n’est pas cumulable est rémunérée comme temps de travail effectif. Le délégué suppléant utilise le crédit d’heures du titulaire qu’il remplace. Le temps consacré aux réunions mensuelles avec les délégués du personnel que l’employeur est tenu d’organiser en application de la règlementation n’est pas déduit de ce crédit d’heures.", resume: "Chaque délégué titulaire dispose de 15 heures par mois, non cumulables et payées comme temps de travail effectif.", motsCles: ["délégué","crédit d'heures","15 heures"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 224" },
  { id: "l24-225", numero: "225", loi: "2024-014", theme: "Syndicats et représentants du personnel", titre: "Comité d'entreprise", texte: "Un comité d’entreprise est mis en place dans toutes les entreprises assujetties au présent Code du travail et occupant à partir de cinquante (50) travailleurs permanents. Le comité d’entreprise, organe consultatif bipartite, est une plate-forme de négociation, de dialogue et de collaboration, intervenant dans le cadre de l'entreprise. Il est consulté et émet son avis sur toutes les questions intéressant la vie des travailleurs : conditions de travail, affaires sociales et culturelles, sécurité, santé et environnement du travail, licenciement individuel ou collectif pour motif économique, différend de travail.", resume: "Un comité d'entreprise est mis en place dans les entreprises occupant à partir de 50 travailleurs permanents. Organe consultatif bipartite, il est consulté notamment sur les conditions de travail, la sécurité et les licenciements économiques.", motsCles: ["comité d'entreprise","50 travailleurs","consultation"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 225" },
  { id: "l24-234", numero: "234", loi: "2024-014", theme: "Règlement intérieur et discipline", titre: "Règlement intérieur : contenu", texte: "Le règlement intérieur est un document écrit en malagasy et/ou en français par lequel l’employeur fixe les règles générales et permanentes relatives à l’organisation technique de l'établissement et à la discipline générale, en déterminant la nature et le degré des sanctions susceptibles d’être prononcées ainsi que les dispositions de procédure garantissant les droits à la défense, les règles de sécurité et de santé nécessaires à sa bonne marche. Toutes autres clauses qui viendraient à y figurer, notamment celles relatives à la rémunération sont considérées comme nulles de plein droit.", resume: "Le règlement intérieur fixe par écrit les règles générales d'organisation technique et de discipline, la nature et le degré des sanctions, les garanties de la défense et les règles de sécurité et de santé. Toute autre clause (notamment sur la rémunération) est nulle.", motsCles: ["règlement intérieur","sanction","discipline","défense"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 234", equivalent: "reglement-interieur" },
  { id: "l24-235", numero: "235", loi: "2024-014", theme: "Règlement intérieur et discipline", titre: "Règlement intérieur obligatoire", texte: "L’élaboration d’un règlement intérieur est obligatoire dans toutes les entreprises employant habituellement plus de onze (11) travailleurs. Lorsqu’une entreprise comprend des établissements distincts, le règlement intérieur de l’entreprise peut comporter des clauses particulières pour tel ou tel établissement.", resume: "Un règlement intérieur est obligatoire dans toutes les entreprises employant habituellement plus de 11 travailleurs.", motsCles: ["règlement intérieur","obligatoire","11 travailleurs"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 235", equivalent: "reglement-obligatoire" },
  { id: "l24-236", numero: "236", loi: "2024-014", theme: "Règlement intérieur et discipline", titre: "Élaboration du règlement intérieur", texte: "L'élaboration du règlement intérieur est du pouvoir de l'employeur. Le projet de règlement intérieur doit être communiqué par l'employeur aux délégués du personnel pour avis. Un Arrêté du Ministre chargé du Travail et de l’emploi fixe : 1. le contenu minimum du règlement intérieur ; 2. les modalités de consultation des délégués du personnel, de visa, de dépôt et d'affichage du règlement intérieur ; 3. le modèle de règlement intérieur ; Les dispositions des alinéas précédents du présent article s’appliquent aux modifications décidées par l’employeur à sa propre initiative ou à la demande des travailleurs.", resume: "Le règlement intérieur relève du pouvoir de l'employeur, qui doit en communiquer le projet aux délégués du personnel pour avis. Un arrêté fixe son contenu minimum, les modalités de visa, dépôt et affichage et un modèle.", motsCles: ["règlement intérieur","délégués","avis","affichage"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 236" },
  { id: "l24-238", numero: "238", loi: "2024-014", theme: "Règlement intérieur et discipline", titre: "Amendes et sanctions pécuniaires interdites", texte: "Il est interdit à l'employeur d'infliger des amendes ou des sanctions pécuniaires sous quelque forme que ce soit.", resume: "Il est interdit à l'employeur d'infliger des amendes ou des sanctions pécuniaires sous quelque forme que ce soit.", motsCles: ["amende","sanction pécuniaire","interdit","retenue"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 238" },
  { id: "l24-239", numero: "239", loi: "2024-014", theme: "Règlement intérieur et discipline", titre: "Délais de la procédure disciplinaire", texte: "Le règlement intérieur doit prévoir : 1. un délai raisonnable d’engagement de la procédure disciplinaire, qui court de la date de constatation des faits et à l’expiration duquel ces faits ne pourront plus faire l’objet d’une procédure disciplinaire ; 2. un délai raisonnable dans lequel l’employeur doit prendre sa décision après la comparution du travailleur au conseil de discipline ou, à défaut, à l’entretien préalable au licenciement ; passé ce délai, aucune sanction ne pourra plus être prise aux motifs des mêmes faits ; 3. un délai raisonnable au-delà duquel une sanction appliquée antérieurement ne pourra plus être invoquée à l’appui d’une nouvelle sanction. Un Décret pris en Conseil de Gouvernement après avis du Conseil National du Travail et de l’Emploi fixe le maximum pour chacun des délais prévus à l’alinéa premier du présent article.", resume: "Le règlement intérieur doit prévoir un délai raisonnable pour engager la procédure disciplinaire après la constatation des faits, un délai pour décider après l'entretien, et un délai au-delà duquel une ancienne sanction ne peut plus être invoquée. Un décret fixe le maximum de ces délais.", motsCles: ["discipline","délai","prescription des faits","sanction"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 239" },
  { id: "l24-240", numero: "240", loi: "2024-014", theme: "Règlement intérieur et discipline", titre: "Suspension conservatoire", texte: "La durée de la suspension conservatoire décidée à l’encontre d’un travailleur en instance disciplinaire doit être strictement limitée au temps nécessaire pour le déroulement de la procédure de licenciement. Durant cette suspension, le travailleur conserve au moins sa rémunération principale ainsi que les avantages non liés à la présence au poste de travail et à la production.", resume: "La suspension conservatoire d'un travailleur en instance disciplinaire doit être limitée au temps nécessaire à la procédure. Il conserve au moins sa rémunération principale et les avantages non liés à la présence.", motsCles: ["mise à pied conservatoire","suspension","discipline","rémunération"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 240" },
  { id: "l24-241", numero: "241", loi: "2024-014", theme: "Conventions collectives", titre: "Convention collective : définition et parties", texte: "La Convention Collective est un contrat écrit relatif aux conditions de travail. Au niveau d’une entreprise où sont employés moins de cinquante (50) travailleurs, la convention collective est conclue entre l’employeur, d'une part, et les délégués du personnel, d'autre part. Au niveau d’une entreprise employant à partir de cinquante (50) travailleurs, la convention collective est conclue au sein du comité d’entreprise.", resume: "La convention collective est un contrat écrit sur les conditions de travail. Elle est conclue entre l'employeur et les délégués du personnel (moins de 50 travailleurs) ou au sein du comité d'entreprise (50 travailleurs et plus).", motsCles: ["convention collective","contrat écrit","délégués du personnel","comité d'entreprise"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 241" },
  { id: "l24-243", numero: "243", loi: "2024-014", theme: "Conventions collectives", titre: "Champ d'application des conventions collectives", texte: "Les conventions collectives déterminent leur champ d'application; celui-ci peut être national, local ou limité à un ou plusieurs établissements, à une ou plusieurs entreprises. Les dispositions de la convention collective ne peuvent déroger aux dispositions d’ordre public.", resume: "Une convention collective fixe son champ d'application (national, local, un ou plusieurs établissements ou entreprises). Elle ne peut pas déroger aux dispositions d'ordre public.", motsCles: ["convention collective","champ d'application","ordre public"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 243" },
  { id: "l24-262", numero: "262", loi: "2024-014", theme: "Inspection du travail et tribunal", titre: "Conciliation devant l'inspection du travail", texte: "Tout travailleur ou tout employeur peut demander à l'inspection du travail de régler le différend à l'amiable.", resume: "Tout travailleur ou employeur peut demander à l'inspection du travail de régler le différend à l'amiable.", motsCles: ["inspection du travail","conciliation","différend"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 262" },
  { id: "l24-263", numero: "263", loi: "2024-014", theme: "Inspection du travail et tribunal", titre: "Saisine obligatoire de l'inspection du travail", texte: "La saisine de l'inspection du travail est obligatoire avant celle de la juridiction compétente pour le règlement des litiges opposant un travailleur encore sous contrat et son employeur. Dans ce cas, les parties sont tenues de se présenter à la convocation sous peine de se voir condamner à la peine prévue à l’article 371 de la présente loi.", resume: "La saisine de l'inspection du travail est obligatoire avant celle du tribunal pour les litiges entre un travailleur encore sous contrat et son employeur. Les parties doivent se présenter à la convocation.", motsCles: ["inspection du travail","saisine","obligatoire","tribunal","conciliation"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 263" },
  { id: "l24-264", numero: "264", loi: "2024-014", theme: "Inspection du travail et tribunal", titre: "Saisine facultative après la rupture", texte: "Par contre, la saisine est facultative dès lors que les relations de travail entre les deux parties ont été rompues. Il en est ainsi en cas de refus de paiement du solde de tout compte par l'employeur.", resume: "Une fois la relation de travail rompue, la saisine de l'inspection du travail est facultative, notamment en cas de refus de paiement du solde de tout compte.", motsCles: ["inspection du travail","rupture","solde de tout compte","facultative"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 264" },
  { id: "l24-267", numero: "267", loi: "2024-014", theme: "Inspection du travail et tribunal", titre: "Procès-verbaux de l'inspecteur", texte: "L'Inspecteur du travail et des lois sociales est tenu de dresser un procès-verbal et, dans un délai d’un mois, d'en délivrer un exemplaire à chacune des parties, quelle que soit l'issue de la procédure de conciliation : 1. un procès-verbal de conciliation, s'il a obtenu l'accord des parties ; 2. un procès-verbal de conciliation partielle, s'il y a désaccord sur certains points ; 3. un procès-verbal de non-conciliation en cas d'échec total de la conciliation ; 4. un procès-verbal de non-exécution si l’une des parties n’a pas exécuté un ou plusieurs points convenus dans le procès-verbal de conciliation totale ou partielle ; 5. un procès-verbal de carence en cas de défaut de comparution de l'une des parties après une troisième convocation.", resume: "L'inspecteur dresse un procès-verbal et en délivre un exemplaire à chaque partie dans un délai d'un mois : conciliation, conciliation partielle, non-conciliation, non-exécution ou carence (3e convocation sans comparution).", motsCles: ["procès-verbal","conciliation","inspecteur","carence"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 267" },
  { id: "l24-271", numero: "271", loi: "2024-014", theme: "Inspection du travail et tribunal", titre: "L'inspecteur du travail peut ordonner le paiement des droits", texte: "L'Inspecteur du travail et des lois sociales détermine les droits du travailleur plaignant prévus dans les textes et ordonne, en conséquence, le rétablissement desdits droits ainsi que le paiement des sommes dues au salarié lésé en vertu des dispositions légales et réglementaires, en cas de: 1. non délivrance de la lettre de licenciement ; 2. non-paiement du salaire ; 3. non-paiement de l’indemnité compensatrice de congé non pris ; 4. non-paiement de l’indemnité de préavis, s’il y a lieu ; 5. non-paiement de l’indemnité de licenciement, s’il y a lieu ; 6. non-délivrance de l’attestation provisoire d’emploi ou du certificat de travail. Le défaut de paiement ou de rétablissement entraîne alors une action directe devant l'instance judiciaire compétente.", resume: "L'inspecteur détermine les droits du travailleur plaignant et ordonne leur rétablissement et le paiement en cas de : non-délivrance de la lettre de licenciement, non-paiement du salaire, des congés non pris, du préavis ou de l'indemnité de licenciement, ou non-délivrance de l'attestation d'emploi ou du certificat de travail. À défaut, action directe devant le tribunal.", motsCles: ["inspecteur","paiement","certificat","salaire","préavis","congés"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 271", equivalent: "inspection-pouvoirs" },
  { id: "l24-272", numero: "272", loi: "2024-014", theme: "Inspection du travail et tribunal", titre: "Compétence du tribunal du travail", texte: "Il est institué, auprès des tribunaux, des juridictions du travail qui connaissent des différends individuels entre le travailleur et son employeur : 1. différends nés de l'interprétation de la loi ou de la convention collective ou des accords d'établissement ; 2. différends nés à l'occasion du contrat de travail ou du contrat d'apprentissage ; 3. des différends non conciliés devant l'inspection du travail régulièrement saisie. Toute affaire déjà réglée au niveau de l'inspection du travail portée devant le tribunal du travail doit être déclarée irrecevable par ce dernier.", resume: "Les juridictions du travail connaissent des différends individuels nés de l'interprétation de la loi ou de la convention, du contrat de travail ou d'apprentissage, et des différends non conciliés devant l'inspection. Une affaire déjà réglée par l'inspection est irrecevable devant le tribunal.", motsCles: ["tribunal du travail","compétence","différend individuel"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 272" },
  { id: "l24-275", numero: "275", loi: "2024-014", theme: "Inspection du travail et tribunal", titre: "Tribunal territorialement compétent", texte: "Le Tribunal compétent est celui du lieu de travail. Toutefois, le travailleur peut également, après rupture du contrat de travail, saisir le tribunal du lieu de son domicile ou celui du domicile de l'employeur. Toute clause contraire aux dispositions des deux alinéas précédents est réputée non écrite.", resume: "Le tribunal compétent est celui du lieu de travail ; après la rupture, le travailleur peut aussi saisir celui de son domicile ou celui du domicile de l'employeur. Toute clause contraire est réputée non écrite.", motsCles: ["tribunal","lieu de travail","domicile","compétence"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 275" },
  { id: "l24-283", numero: "283", loi: "2024-014", theme: "Grève et conflits collectifs", titre: "Droit de grève : quand est-il acquis ?", texte: "Le droit de grève ou le lock-out est acquis à la date de la constatation par l’inspection du travail du constat d’échec total ou partiel de la négociation, sous réserve de l’observation d’un délai de préavis de deux (2) jours ouvrables adressé par lettre recommandée à l’autre partie. Copie de cette lettre de préavis est communiquée au médiateur, dans le même délai que celui prévu à l’alinéa premier du présent article.", resume: "Le droit de grève (ou de lock-out) est acquis à la date où l'inspection du travail constate l'échec total ou partiel de la négociation, sous réserve d'un préavis de 2 jours ouvrables adressé par lettre recommandée à l'autre partie.", motsCles: ["grève","préavis de grève","négociation","inspection"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 283" },
  { id: "l24-296", numero: "296", loi: "2024-014", theme: "Grève et conflits collectifs", titre: "Droit de grève", texte: "Le droit de grève, reconnu et garanti par la Constitution, s'exerce dans le cadre des textes en vigueur. La grève est un arrêt complet, concerté et collectif du travail décidé par des salariés d'une entreprise ou d'un établissement pour faire aboutir des revendications professionnelles qui n’ont pas été satisfaites. Le droit de grève des salariés soumis à la présente loi ne peut être limité par la réquisition qu’en cas de crise nationale aiguë, ou dans le cas où la grève mettrait en danger la vie, la sécurité ou la santé de tout ou partie de la population.", resume: "Le droit de grève est garanti par la Constitution. La grève est un arrêt complet, concerté et collectif du travail pour faire aboutir des revendications professionnelles non satisfaites. La réquisition ne peut limiter ce droit qu'en cas de crise nationale aiguë ou de danger pour la vie, la sécurité ou la santé de la population.", motsCles: ["grève","droit de grève","réquisition","revendications"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 296" },
  { id: "l24-297", numero: "297", loi: "2024-014", theme: "Grève et conflits collectifs", titre: "Service minimum", texte: "Dans les établissements et entreprises assurant des prestations de service public, un service minimum doit être assuré durant l’exercice du droit de grève. Les modalités de sa mise en œuvre sont fixées par la convention collective ou par toute autre forme d’accord collectif.", resume: "Dans les établissements assurant des prestations de service public, un service minimum doit être assuré pendant la grève, selon les modalités fixées par la convention collective ou un accord collectif.", motsCles: ["grève","service minimum","service public"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 297" },
  { id: "l24-298", numero: "298", loi: "2024-014", theme: "Grève et conflits collectifs", titre: "Effets de la grève licite", texte: "La grève licite suspend le contrat de travail ; le salarié est dispensé de fournir sa prestation habituelle de travail ; il recouvre son emploi en fin de grève et ne peut pas être sanctionné du fait de sa participation à la grève ; l’employeur est dispensé de verser au salarié sa rémunération habituelle. Les accords de fin de grève conclus entre l'employeur et les travailleurs peuvent néanmoins prévoir l’octroi d’une indemnité compensant en tout ou partie la perte de salaire due à la grève. Ils peuvent également prévoir le recours soit à des heures supplémentaires, soit à des heures de récupération pour compenser en tout ou en partie les conséquences de la grève. Les salariés peuvent demander auprès de la juridiction compétente des dommages intérêts réparant le préjudice qu’ils ont subi du fait du recours à la grève.", resume: "La grève licite suspend le contrat : le salarié est dispensé de travailler, l'employeur de le payer. Le salarié retrouve son emploi à la fin de la grève et ne peut être sanctionné pour y avoir participé.", motsCles: ["grève","suspension","sanction","salaire"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 298" },
  { id: "l24-353", numero: "353", loi: "2024-014", theme: "Sanctions pénales", titre: "Infractions à la liberté syndicale et au droit de grève", texte: "Sera puni d’une amende de un million d’Ariary au moins et de quatre millions d’Ariary au plus quiconque aura, par des agissements de quelque nature que ce soit : 1. empêché la constitution d’une organisation syndicale d’employeurs ou de travailleurs ; 2. empêché la liberté de tout employeur ou de tout travailleur d’adhérer à une organisation syndicale ou de ne pas y adhérer ; 3. empêché l’exercice des fonctions des délégués syndicaux et des dirigeants syndicaux désignés conformément aux lois et règlements, aux statuts et au règlement intérieur de l’organisation d’appartenance ; 4. empêché toute activité légalement menée par les syndicats en vue de la défense des intérêts de leurs membres ; 5. exercé des représailles ou des actes de harcèlement moral basés sur l’appartenance syndicale ; 6. empêché par sanction, licenciement ou menace de sanction ou menace de licenciement la participation des travailleurs à une grève licite ; 7. été reconnu comme meneur, instigateur ou complice d’actes de violence ou de voie de fait commis à l’occasion d’une grève ou d’un lock-out ; 8. commis des actes d’ingérence dans l’organisation et les affaires internes des syndicats. En cas de récidive, la peine d’amende sera portée au double et une peine d’emprisonnement de un (01) mois à six (06) mois sera prononcée.", resume: "Amende de 1 à 4 millions d'Ariary pour quiconque entrave notamment la constitution d'un syndicat, l'exercice des fonctions des délégués syndicaux, exerce des représailles pour appartenance syndicale ou empêche par sanction ou menace la participation à une grève licite. Récidive : amende doublée et prison de 1 à 6 mois.", motsCles: ["sanction pénale","syndicat","grève","amende"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 353" },
  { id: "l24-356", numero: "356", loi: "2024-014", theme: "Sanctions pénales", titre: "Discrimination : sanctions pénales", texte: "Sera puni d’une amende de un million d’Ariary au moins à quatre millions d’Ariary au plus quiconque aura utilisé la race, la couleur, la religion, l'opinion politique, l'ascendance nationale ou l'origine sociale, l’état de santé, le handicap, l’appartenance syndicale, l’âge, le genre, le sexe et le cas d’une situation liée à la grossesse pour faire directement ou indirectement une distinction ou une exclusion ou accorder une préférence en matière d’accès à l’emploi, de rémunération, de sanction, de conditions de travail, de progression dans l’emploi et la carrière, de licenciement ou de tout autre aspect du traitement des travailleurs ou des candidats à l’emploi. En cas de récidive, la peine d’amende sera portée au double et une peine d’emprisonnement de un (01) mois au moins à six (06) mois au plus sera prononcée.", resume: "Amende de 1 à 4 millions d'Ariary pour toute distinction, exclusion ou préférence fondée sur la race, la couleur, la religion, l'opinion politique, l'origine, la santé, le handicap, le syndicat, l'âge, le genre, le sexe ou la grossesse en matière d'emploi, de rémunération, de sanction ou de licenciement. Récidive : amende doublée et prison de 1 à 6 mois.", motsCles: ["discrimination","sanction pénale","amende","grossesse"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 356", equivalent: "discrimination-penal" },
  { id: "l24-357", numero: "357", loi: "2024-014", theme: "Sanctions pénales", titre: "Harcèlement sexuel : sanction", texte: "Quiconque se sera rendu coupable de harcèlement sexuel au travail tel que défini l’article 11 de la présente loi sera sanctionné conformément aux dispositions du Code pénal.", resume: "Le harcèlement sexuel au travail est sanctionné conformément au Code pénal.", motsCles: ["harcèlement sexuel","sanction pénale","Code pénal"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 357" },
  { id: "l24-358", numero: "358", loi: "2024-014", theme: "Sanctions pénales", titre: "Harcèlement moral : sanction pénale", texte: "Quiconque se sera rendu coupable de harcèlement moral au travail tel que défini à l’article 12 de la présente loi sera puni d’un emprisonnement trois (03) mois au moins à un (01) an au plus et d’une amende de un million d’Ariary au moins et de quatre millions d’Ariary au plus, ou de l’une de ces deux peines seulement. En cas de récidive, la peine sera portée au double.", resume: "Le harcèlement moral au travail est puni de 3 mois à 1 an de prison et d'une amende de 1 à 4 millions d'Ariary, ou de l'une de ces deux peines. En cas de récidive, la peine est doublée.", motsCles: ["harcèlement moral","sanction pénale","prison","amende"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 358" },
  { id: "l24-359", numero: "359", loi: "2024-014", theme: "Sanctions pénales", titre: "Maternité : infractions", texte: "Sera puni d’une amende de un million d’Ariary au moins à quatre millions d’Ariary au plus tout employeur qui : 1. aura employé une femme dont la grossesse est connue, dans des travaux interdits par le décret visé à l’article 137 de la présente loi ou reconnus comme comportant un risque significatif pour la santé de la femme et de l’enfant, tel que prévu aux articles 138 et 139 de la présente loi ; 2. aura, au mépris de l’interdiction prévue à l’article 146, employé la nuit une femme enceinte. En cas de récidive, la peine sera portée au double.", resume: "Amende de 1 à 4 millions d'Ariary pour l'employeur qui emploie une femme enceinte à des travaux interdits ou à risque, ou la fait travailler la nuit en violation de l'interdiction.", motsCles: ["maternité","sanction pénale","nuit","travaux interdits"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 359" },
  { id: "l24-360", numero: "360", loi: "2024-014", theme: "Sanctions pénales", titre: "Travail des enfants de moins de 15 ans : sanction", texte: "Sera puni d’un emprisonnement de trois (03) mois au moins à un (01) an au plus et d’une amende de un million d’Ariary au moins à quatre millions d’Ariary au plus, quiconque aura employé ou facilité l’emploi d’un enfant de moins de quinze ans, en violation des dispositions des articles 147 à 151 du présent Code et des textes règlementaires prise en leur application. En cas de récidive, la peine sera portée au double.", resume: "Emprisonnement de 3 mois à 1 an et amende de 1 à 4 millions d'Ariary pour quiconque emploie ou facilite l'emploi d'un enfant de moins de 15 ans en violation des articles 147 à 151.", motsCles: ["enfants","sanction pénale","prison","15 ans"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 360" },
  { id: "l24-362", numero: "362", loi: "2024-014", theme: "Sanctions pénales", titre: "Travail forcé : sanction", texte: "Sera puni d’un emprisonnement de trois (03) mois au moins à un (01) an au plus et d’une amende de un million d’Ariary au moins à quatre millions d’Ariary au plus ou de l’une de ces deux peines seulement, quiconque aura fait faire à une autre personne du travail forcé ou obligatoire tel que défini et interdit à l’article 4 du présent Code. En cas de récidive, la peine sera portée au double.", resume: "Emprisonnement de 3 mois à 1 an et amende de 1 à 4 millions d'Ariary (ou l'une de ces peines) pour quiconque fait faire à une autre personne un travail forcé ou obligatoire.", motsCles: ["travail forcé","sanction pénale"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 362" },
  { id: "l24-363", numero: "363", loi: "2024-014", theme: "Sanctions pénales", titre: "Sécurité : lieux de travail dangereux", texte: "Sera puni d’un emprisonnement de trois mois au moins à un an au plus et d’une amende de un million d’Ariary au moins à quatre million d’Ariary au plus ou de l’une de ces deux peines seulement tout employeur qui, malgré la mise en demeure de l’Inspecteur du travail et des lois sociales du ressort notifiée dans les conditions prévues à l’article 380 du présent Code aura, en violation des articles 163, 165, 166 et 173 du présent Code ainsi que des textes règlementaires pris en leur application, employé des travailleurs dans un lieu de travail, y compris les dépendances, qui présente des risques certains pour la sécurité et la santé des travailleurs et sans les moyens et mesures de protection collective et individuelle requis.", resume: "Emprisonnement de 3 mois à 1 an et/ou amende de 1 à 4 millions d'Ariary pour l'employeur qui, malgré mise en demeure de l'inspecteur, emploie des travailleurs dans un lieu présentant des risques certains sans protection collective et individuelle (articles 163, 165, 166 et 173).", motsCles: ["sécurité","sanction pénale","mise en demeure","protection"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 363" },
  { id: "l24-369", numero: "369", loi: "2024-014", theme: "Sanctions pénales", titre: "Salaire, mensualisation, bulletin de paie : sanctions", texte: "Sera puni d’une amende de 1 million d’Ariary au moins à 4 millions d’Ariary au plus tout employeur qui, malgré la mise en demeure de l’Inspecteur du travail et des lois sociales du ressort notifiée dans les conditions prévues à l’article 380 du présent Code : 1. aura, en violation des dispositions de l’article 91 du présent Code, payé le salaire en monnaie autre que celle ayant cours légal ou en boisson alcoolisée; 2. n’aura pas appointé au mois les travailleurs payés à l’heure ou à la journée remplissant les conditions fixées par l’article 86 du présent Code; 3. ne se sera pas conformé à l’obligation de délivrer un bulletin de paye dans les conditions prévues par l’article 95 du présent Code et les textes règlementaires pris en son application. En cas de récidive, la peine sera portée au double.", resume: "Amende de 1 à 4 millions d'Ariary, après mise en demeure de l'inspecteur, pour l'employeur qui paie en monnaie non légale ou en alcool, n'applique pas la mensualisation ou ne délivre pas de bulletin de paie.", motsCles: ["salaire","bulletin de paie","sanction pénale","amende"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 369" },
  { id: "l24-370", numero: "370", loi: "2024-014", theme: "Sanctions pénales", titre: "Repos, jours fériés, congés : sanctions", texte: "Sera puni d’une amende de un million d’Ariary au moins à quatre millions d’Ariary au plus, tout employeur ou son représentant qui, malgré la mise en demeure de l’Inspecteur du travail et des lois sociales du ressort notifiée dans les conditions prévues à l’article 380 du présent Code: 1. aura, en violation de l’article 113 du présent Code, refusé d’accorder au travailleur le repos journalier ; 2. aura, en violation de l’article 114 du présent Code et des textes règlementaires pris en son application, refusé d’accorder au travailleur le repos hebdomadaire ; 3. aura, en violation de l’article 115 du présent Code, employé un jour férié un travailleur autre que ceux indiqués dans les dérogations accordées par le décret fixant annuellement la liste des jours fériés ; 4. n’aura pas fait bénéficier aux travailleurs de nuit les mesures sanitaires prévues aux articles 119 et 120 du présent Code; 5. n’aura pas, en violation de l’article 124 du présent Code et des textes règlementaires pris en son application, assuré le transport et la sécurité du personnel travaillant la nuit ; 6. n’aura pas accordé tout ou partie de la jouissance du droit au congé annuel du travailleur prévu aux articles 125 à 133 du présent Code. En cas de récidive, la peine sera portée au double.", resume: "Amende de 1 à 4 millions d'Ariary, après mise en demeure, pour l'employeur qui refuse le repos journalier ou hebdomadaire, emploie un jour férié hors dérogation, néglige les mesures sanitaires de nuit ou refuse tout ou partie du congé annuel.", motsCles: ["repos","congés","férié","sanction pénale"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 370" },
  { id: "l24-372", numero: "372", loi: "2024-014", theme: "Sanctions pénales", titre: "Contrat écrit : sanction", texte: "Sera puni d’une amende de un million d’Ariary au moins à quatre millions d’Ariary au plus tout employeur qui, malgré la mise en demeure de l’Inspecteur du travail et des lois sociales du ressort notifiée dans les conditions prévues à l’article 380 du présent Code: 1. n’aura pas établi de contrat de travail écrit conformément aux règles prévues par le présent Code quant au contenu et à la forme, y compris en ce qui concerne la langue à utiliser ; 2. n’aura pas délivré un exemplaire du contrat de travail au travailleur ou à l’apprenti. En cas de récidive, la peine sera portée au double.", resume: "Amende de 1 à 4 millions d'Ariary, après mise en demeure, pour l'employeur qui n'a pas établi de contrat écrit conforme ou n'en a pas remis d'exemplaire au travailleur ou à l'apprenti.", motsCles: ["contrat écrit","sanction pénale","amende"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 372" },
  { id: "l24-380", numero: "380", loi: "2024-014", theme: "Sanctions pénales", titre: "Mise en demeure de l'inspecteur", texte: "Lorsqu’une mise en demeure de l’Inspecteur du travail et des lois sociales du ressort est prévue dans le cadre des dispositions du présent Titre, son destinataire dispose en principe d’un délai de trente jours francs à compter de la notification. Toutefois, l’Inspecteur du travail et des lois sociales peut toujours accorder un délai plus court si, compte tenu de la nature de l’infraction combinée aux circonstances entourant sa survenance, il estime qu’il y a urgence à ce que la situation soit le plus rapidement possible redressée. De même, lorsqu’aucune mise en demeure n’est prévue, l’Inspecteur du travail et des lois sociales, s’il estime que la situation peut raisonnablement être redressée, peut toujours accorder un délai à l’auteur de l’infraction pour y procéder. Passé ces délais de mise en demeure, si l’auteur n’a pris aucune mesure significative pour redresser la situation ou faire cesser les agissements illégaux, l’infraction est constituée et l’Inspecteur du travail et des lois sociales du ressort la constate par le procès-verbal prévu à l’article 382 du présent Code.", resume: "Quand une mise en demeure est prévue, son destinataire dispose en principe de 30 jours francs ; l'inspecteur peut accorder un délai plus court en cas d'urgence. Passé ce délai sans mesure significative, l'infraction est constituée et constatée par procès-verbal.", motsCles: ["mise en demeure","30 jours","inspecteur","infraction"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 380" },
  { id: "l24-391", numero: "391", loi: "2024-014", theme: "Dispositions transitoires et finales", titre: "Textes réglementaires antérieurs maintenus", texte: "Jusqu’à l’adoption des textes règlementaires de remplacement, ceux pris en application des Codes du travail antérieurs et de l’ancienne Loi n° 94- 027 du 17 novembre 1994 portant Code d’hygiène, de sécurité et d'environnement du travail demeurent applicables en toutes leurs dispositions non contraires à la présente loi.", resume: "Jusqu'à l'adoption des textes réglementaires de remplacement, ceux pris en application des anciens Codes du travail et de la loi n° 94-027 sur l'hygiène et la sécurité demeurent applicables dans leurs dispositions non contraires à la nouvelle loi.", motsCles: ["décrets","transition","textes antérieurs","entrée en vigueur"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 391" },
  { id: "l24-392", numero: "392", loi: "2024-014", theme: "Dispositions transitoires et finales", titre: "Application aux contrats en cours", texte: "Les dispositions du présent Code du travail sont, de plein droit, applicables aux contrats individuels de travail en cours. Elles ne peuvent constituer une cause de rupture de ces contrats. Toute clause d'un contrat de travail en cours qui ne serait pas conforme aux dispositions du présent Code du travail ainsi qu’à celles des textes réglementaires pris en son application est considérée comme modifiée de plein droit par ces textes.", resume: "Le nouveau Code est de plein droit applicable aux contrats individuels en cours et ne peut constituer une cause de rupture. Toute clause non conforme est considérée comme modifiée de plein droit.", motsCles: ["contrats en cours","transition","clause","application"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 392" },
  { id: "l24-393", numero: "393", loi: "2024-014", theme: "Dispositions transitoires et finales", titre: "Conventions collectives maintenues", texte: "Les conventions collectives restent en vigueur en celles de leurs dispositions qui ne sont pas contraires au présent Code et peuvent faire l'objet de décrets d'extension.", resume: "Les conventions collectives restent en vigueur dans celles de leurs dispositions qui ne sont pas contraires au nouveau Code et peuvent faire l'objet de décrets d'extension.", motsCles: ["convention collective","transition","extension"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 393" },
  { id: "l24-394", numero: "394", loi: "2024-014", theme: "Dispositions transitoires et finales", titre: "Abrogation de la loi 2003-044", texte: "Sont et demeurent abrogées toutes dispositions antérieures contraires au présent Code, notamment celles de la Loi n° 2003-044 du 28 juillet 2004 portant Code du travail.", resume: "Sont abrogées toutes dispositions antérieures contraires au Code, notamment celles de la loi n° 2003-044 du 28 juillet 2004 portant Code du travail.", motsCles: ["abrogation","loi 2003-044","transition"], verifie: true, source: "Loi n° 2024-014 du 14 août 2024, art. 394" },
];
